@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        conn = sqlite3.connect('ProjectStatus.db')
        c = conn.cursor()
        # The users table schema is: (id, username, password, role)
        c.execute("SELECT * FROM users WHERE username=?", (username,))
        user = c.fetchone()
        
        # Check password (support both hashed and legacy plaintext passwords)
        password_valid = False
        if user:
            stored_password = user[2]
            # Try hashed password first (new format)
            try:
                if check_password_hash(stored_password, password):
                    password_valid = True
            except ValueError:
                # Not a valid hash format, try plaintext comparison
                pass
            
            # Fallback: check if it's a legacy plaintext password
            if not password_valid and stored_password == password:
                password_valid = True
                # Auto-upgrade to hashed password
                hashed_password = generate_password_hash(password)
                c.execute("UPDATE users SET password=? WHERE username=?", (hashed_password, username))
                # Also update engineers table if user is an engineer
                c.execute("UPDATE engineers SET password=? WHERE username=?", (hashed_password, username))
                conn.commit()
        
        conn.close()

        if password_valid:
            session['user_id'] = user[0]
            session['username'] = user[1]
            session['user_role'] = user[3]  # Save user's role in the session
            
            # Generate a unique session ID for tracking
            session_id = str(uuid.uuid4())
            session['session_id'] = session_id
            
            # Record active session in database
            conn2 = sqlite3.connect('ProjectStatus.db')
            c2 = conn2.cursor()
            # Remove any existing sessions for this user (enforce single session)
            c2.execute("DELETE FROM active_sessions WHERE user_id = ?", (user[0],))
            # Insert new session
            c2.execute("""
                INSERT INTO active_sessions (user_id, username, role, session_id, login_time, last_activity, ip_address, user_agent)
                VALUES (?, ?, ?, ?, datetime('now'), datetime('now'), ?, ?)
            """, (user[0], user[1], user[3], session_id, request.remote_addr, request.headers.get('User-Agent', '')[:500]))
            conn2.commit()
            conn2.close()
            
            # Load user permissions into session
            refresh_user_permissions()

            flash('Login successful!', 'success')
            return redirect(url_for('index'))
        else:
            flash('Invalid username or password!', 'danger')

    return render_template('login.html')
