@app.route('/company_profile')
@login_required
def company_profile():
    """Company Profile page showing EJTech company information"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    # Create tables if not exists
    c.execute("""
        CREATE TABLE IF NOT EXISTS company_profile_content (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            section_key TEXT UNIQUE NOT NULL,
            content TEXT,
            updated_by TEXT,
            updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)
    c.execute("""
        CREATE TABLE IF NOT EXISTS company_solutions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            icon TEXT NOT NULL,
            color_class TEXT DEFAULT 'purple',
            display_order INTEGER DEFAULT 0,
            image_url TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)
    # Add image_url column if it doesn't exist
    try:
        c.execute("ALTER TABLE company_solutions ADD COLUMN image_url TEXT")
        conn.commit()
    except:
        pass  # Column already exists
    
    # Create company_clients table
    c.execute("""
        CREATE TABLE IF NOT EXISTS company_clients (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            sector TEXT DEFAULT '',
            image_url TEXT,
            display_order INTEGER DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        )
    """)
    conn.commit()
    
    # Create featured_projects table
    c.execute("""
        CREATE TABLE IF NOT EXISTS featured_projects (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            scope TEXT DEFAULT '',
            location TEXT DEFAULT '',
            year TEXT DEFAULT '',
            icon TEXT DEFAULT 'fa-building',
            display_order INTEGER DEFAULT 0,
            client_id INTEGER,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (client_id) REFERENCES company_clients(id)
        )
    """)
    conn.commit()
    
    # Add client_id column to featured_projects if it doesn't exist
    try:
        c.execute("ALTER TABLE featured_projects ADD COLUMN client_id INTEGER")
        conn.commit()
    except:
        pass  # Column already exists
    
    # Create client_certificates table
