@app.route('/upload_supplier_quotation', methods=['POST'])
@login_required
def upload_supplier_quotation():
    """Upload supplier quotation PDF for a specific quotation with distributor/vendor tracking"""
    try:
        quote_ref = request.form.get('quote_ref')
        distributor_id_str = request.form.get('distributor_id')
        vendor_id_str = request.form.get('vendor_id')
        system = request.form.get('system', '')
        notes = request.form.get('notes', '')
        
        if not quote_ref:
            flash('Quote reference is required!', 'danger')
            return redirect(request.referrer or url_for('index'))
        
        # Validate at least one supplier is selected
        if not distributor_id_str and not vendor_id_str:
            flash('Please select at least one distributor or vendor!', 'danger')
            return redirect(request.referrer or url_for('index'))
        
        # Get the uploaded file
        quotation_file = request.files.get('supplier_quotation_file')
        if not quotation_file or quotation_file.filename == '':
            flash('Please select a PDF file to upload!', 'danger')
            return redirect(request.referrer or url_for('index'))
        
        # Validate file type
        if not quotation_file.filename.lower().endswith('.pdf'):
            flash('Only PDF files are allowed!', 'danger')
            return redirect(request.referrer or url_for('index'))
        
        # Read file data
        quotation_data = quotation_file.read()
        filename = quotation_file.filename
        
        conn = sqlite3.connect('ProjectStatus.db')
        cursor = conn.cursor()
        
        # Get distributor name if selected
        distributor_id = None
        distributor_name = None
        if distributor_id_str:
            distributor_id = int(distributor_id_str)
            cursor.execute("SELECT name FROM distributors WHERE id = ?", (distributor_id,))
            result = cursor.fetchone()
            distributor_name = result[0] if result else None
        
        # Get vendor name if selected
        vendor_id = None
        vendor_name = None
        if vendor_id_str:
            vendor_id = int(vendor_id_str)
            cursor.execute("SELECT name FROM vendors WHERE id = ?", (vendor_id,))
            result = cursor.fetchone()
            vendor_name = result[0] if result else None
        
        # Insert the supplier quotation
        cursor.execute("""
            INSERT INTO supplier_quotations 
            (quote_ref, distributor_id, distributor_name, vendor_id, vendor_name, 
             system, quotation_file, filename, uploaded_by, notes)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (quote_ref, distributor_id, distributor_name, vendor_id, vendor_name,
              system, quotation_data, filename, session['username'], notes))
        
        conn.commit()
        conn.close()
        
        # Build success message
        supplier_names = []
        if distributor_name:
            supplier_names.append(f"Distributor: {distributor_name}")
        if vendor_name:
            supplier_names.append(f"Vendor: {vendor_name}")
        
        flash(f'Supplier quotation uploaded successfully for {", ".join(supplier_names)}!', 'success')
        return redirect(request.referrer or url_for('index'))
        
    except Exception as e:
        flash(f'Error uploading supplier quotation: {str(e)}', 'danger')
        return redirect(request.referrer or url_for('index'))

@app.route('/download_supplier_quotation/<int:quotation_id>', methods=['GET'])
@login_required
def download_supplier_quotation(quotation_id):
    """View or Download a specific supplier quotation PDF"""
    try:
        action = request.args.get('action', 'download')  # Default to download
        
        conn = sqlite3.connect('ProjectStatus.db')
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT quotation_file, filename, distributor_name, vendor_name 
            FROM supplier_quotations 
            WHERE id = ?
        """, (quotation_id,))
        
        result = cursor.fetchone()
        conn.close()
        
        if result and result[0]:
            quotation_data = result[0]
            filename = result[1]
            supplier_name = result[2] or result[3]
            
            output = BytesIO(quotation_data)
            
            # If action is 'view', display inline; otherwise download
            if action == 'view':
                return send_file(output, mimetype='application/pdf', as_attachment=False, download_name=filename)
            else:
                return send_file(output, download_name=filename, as_attachment=True, mimetype='application/pdf')
        else:
            flash('Supplier quotation not found!', 'danger')
            return redirect(request.referrer or url_for('index'))
            
    except Exception as e:
        flash(f'Error accessing supplier quotation: {str(e)}', 'danger')
        return redirect(request.referrer or url_for('index'))


# Upload Project Documents (BOQ, Spec, Google Drive Link)
@app.route('/upload_project_documents/<int:project_id>', methods=['POST'])
@login_required
def upload_project_documents(project_id):
    """Upload or update project documents (BOQ, Spec, Google Drive Link)"""
    try:
        conn = sqlite3.connect('ProjectStatus.db')
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        
        # Get project details
        cursor.execute("SELECT project_name FROM register_project WHERE id = ?", (project_id,))
        project = cursor.fetchone()
        
        if not project:
            flash('Project not found!', 'danger')
            conn.close()
            return redirect(url_for('view_projects'))
        
        project_name = project['project_name']
        
        # Get Google Drive link from form
        gdrive_link = request.form.get('gdrive_link', '').strip()
        
        # Get uploaded files
        boq_file = request.files.get('boq_file')
        spec_file = request.files.get('spec_file')
        
        # Validate file types
        allowed_boq_extensions = {'.xlsx', '.xls'}
        allowed_spec_extensions = {'.pdf'}
        
        boq_data = None
        boq_filename = None
        spec_data = None
        spec_filename = None
        
        if boq_file and boq_file.filename:
            file_ext = os.path.splitext(boq_file.filename)[1].lower()
            if file_ext not in allowed_boq_extensions:
                flash('BOQ file must be Excel format (.xlsx or .xls)!', 'danger')
                conn.close()
                return redirect(url_for('project_detail', project_id=project_id))
            
            boq_data = boq_file.read()
            boq_filename = boq_file.filename
        
        if spec_file and spec_file.filename:
            file_ext = os.path.splitext(spec_file.filename)[1].lower()
            if file_ext not in allowed_spec_extensions:
                flash('Specification file must be PDF format!', 'danger')
                conn.close()
                return redirect(url_for('project_detail', project_id=project_id))
            
            spec_data = spec_file.read()
            spec_filename = spec_file.filename
        
        # Check if documents already exist for this project
        cursor.execute("SELECT id FROM project_docs WHERE project_id = ?", (project_id,))
        existing = cursor.fetchone()
        
        if existing:
            # Update existing record
            update_fields = []
            update_params = []
            
            if boq_data:
                update_fields.append("boq_file = ?")
                update_fields.append("boq_filename = ?")
                update_params.extend([boq_data, boq_filename])
            
            if spec_data:
                update_fields.append("spec_file = ?")
                update_fields.append("spec_filename = ?")
                update_params.extend([spec_data, spec_filename])
            
            if gdrive_link:
                update_fields.append("gdrive_link = ?")
                update_params.append(gdrive_link)
            
            if update_fields:
                update_fields.append("uploaded_by = ?")
                update_fields.append("uploaded_at = CURRENT_TIMESTAMP")
                update_params.append(session.get('username'))
                update_params.append(existing['id'])
                
                query = f"UPDATE project_docs SET {', '.join(update_fields)} WHERE id = ?"
                cursor.execute(query, update_params)
                flash('Project documents updated successfully!', 'success')
            else:
                flash('No documents were uploaded or updated!', 'warning')
        else:
            # Insert new record
            cursor.execute("""
                INSERT INTO project_docs 
                (project_id, project_name, boq_file, boq_filename, spec_file, spec_filename, gdrive_link, uploaded_by)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """, (project_id, project_name, boq_data, boq_filename, spec_data, spec_filename, gdrive_link, session.get('username')))
            flash('Project documents uploaded successfully!', 'success')
        
        conn.commit()
        conn.close()
        return redirect(url_for('project_detail', project_id=project_id))
        
    except Exception as e:
        flash(f'Error uploading documents: {str(e)}', 'danger')
        return redirect(url_for('project_detail', project_id=project_id))


