@app.route('/registered_quotations')
@permission_required('view_reports')
def registered_quotations():
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()

    # Get filter values from URL
    filters = {
        'start_registered': request.args.get('start_registered_date'),
        'end_registered': request.args.get('end_registered_date'),
        'start_updated': request.args.get('start_updated_date'),
        'end_updated': request.args.get('end_updated_date'),
        'sales_eng': request.args.get('sales_eng'),
        'presale_eng': request.args.get('presale_eng')
    }

    # Base query updated to select quotation_cost, rfq_reference and rfq_id
    query = """
        SELECT p.id, p.project_name, p.quote_ref, p.presale_eng, p.sales_eng, p.status, 
               p.quotation_selling_price, p.margin, p.registered_date, p.updated_time,
               p.quotation_cost, p.rfq_reference,
               (SELECT rp.id FROM register_project rp WHERE rp.project_name = p.project_name LIMIT 1) as project_id,
               (SELECT r.id FROM rfq_requests r WHERE r.rfq_reference = p.rfq_reference LIMIT 1) as rfq_id
        FROM projects p
        WHERE 1=1
    """
    params = []

    # Apply filters to the query
    if filters['start_registered']: query += " AND date(registered_date) >= ?"; params.append(
        filters['start_registered'])
    if filters['end_registered']: query += " AND date(registered_date) <= ?"; params.append(filters['end_registered'])
    if filters['start_updated']: query += " AND date(updated_time) >= ?"; params.append(filters['start_updated'])
    if filters['end_updated']: query += " AND date(updated_time) <= ?"; params.append(filters['end_updated'])
    if filters['sales_eng']: query += " AND sales_eng = ?"; params.append(filters['sales_eng'])
    if filters['presale_eng']: query += " AND presale_eng = ?"; params.append(filters['presale_eng'])

    query += " ORDER BY registered_date DESC"
    c.execute(query, params)
    quotations = c.fetchall()

    # Fetch engineers for filter dropdowns based on registered quotation data
    c.execute("SELECT DISTINCT sales_eng FROM projects WHERE sales_eng IS NOT NULL AND sales_eng != '' ORDER BY sales_eng")
    sales_engineers = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT presale_eng FROM projects WHERE presale_eng IS NOT NULL AND presale_eng != '' ORDER BY presale_eng")
    presale_engineers = [row[0] for row in c.fetchall()]
    conn.close()

    is_admin = session.get('username', '').lower() == 'm.saleh'
    
    return render_template('registered_quotations.html',
                           quotations=quotations,
                           presale_engineers=presale_engineers,
                           sales_engineers=sales_engineers,
                           current_filters=filters,
                           is_admin=is_admin)


@app.route('/api/quotation/<int:quotation_id>', methods=['DELETE'])
@login_required
def delete_quotation(quotation_id):
    """Delete a quotation by ID - Admin only (M.Saleh)"""
    if session.get('username', '').lower() != 'm.saleh':
        return jsonify({'success': False, 'error': 'Unauthorized. Admin access required.'}), 403
    
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    # Check if quotation exists and get quote_ref
    c.execute("SELECT id, quote_ref FROM projects WHERE id = ?", (quotation_id,))
    quotation = c.fetchone()
    
    if not quotation:
        conn.close()
        return jsonify({'success': False, 'error': 'Quotation not found'}), 404
    
    quote_ref = quotation[1]
    
    # Delete quotation products for this specific quotation
    c.execute("DELETE FROM quotation_products WHERE quote_ref = ? AND id IN (SELECT qp.id FROM quotation_products qp WHERE qp.quote_ref = ? LIMIT 1)", (quote_ref, quote_ref))
    
    # Delete only this specific quotation by ID
    c.execute("DELETE FROM projects WHERE id = ?", (quotation_id,))
    
    conn.commit()
    conn.close()
    
    return jsonify({'success': True, 'message': 'Quotation deleted successfully'})


@app.route('/engineer_reports')
@login_required
def engineer_reports():
    """Engineer Reports - View projects and quotations by Sales or Presale Engineer"""
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    report_type = request.args.get('type', 'sales')
    selected_engineer = request.args.get('engineer', '')
    selected_year = request.args.get('year', '')
    selected_quarter = request.args.get('quarter', '')
    selected_month = request.args.get('month', '')
    selected_week = request.args.get('week', '')
    
    # Get available years from projects
    c.execute("SELECT DISTINCT strftime('%Y', registered_date) as year FROM projects WHERE registered_date IS NOT NULL ORDER BY year DESC")
    years = [row[0] for row in c.fetchall() if row[0]]
    
    # Get list of engineers based on report type
    if report_type == 'sales':
        c.execute("SELECT DISTINCT sales_eng FROM projects WHERE sales_eng IS NOT NULL AND sales_eng != '' ORDER BY sales_eng")
    else:
        c.execute("SELECT DISTINCT presale_eng FROM projects WHERE presale_eng IS NOT NULL AND presale_eng != '' ORDER BY presale_eng")
    
    engineers = [row[0] for row in c.fetchall()]
    
    projects = []
    total_quotations = 0
    
    if selected_engineer:
        # Build date filter conditions
        date_conditions = ""
        params_base = [selected_engineer]
        
        if selected_year:
            date_conditions += " AND strftime('%Y', registered_date) = ?"
            params_base.append(selected_year)
        
        # Month filter takes priority over quarter if both are set
        if selected_month:
            date_conditions += " AND strftime('%m', registered_date) = ?"
            params_base.append(selected_month)
            
            # Week filter only applies when month is selected
            if selected_week:
                # Calculate week of month based on day: Week 1 = days 1-7, Week 2 = days 8-14, etc.
                week_num = int(selected_week)
                start_day = (week_num - 1) * 7 + 1
                end_day = week_num * 7
                date_conditions += " AND CAST(strftime('%d', registered_date) AS INTEGER) BETWEEN ? AND ?"
                params_base.extend([start_day, end_day])
        elif selected_quarter:
            quarter_map = {'Q1': ('01', '03'), 'Q2': ('04', '06'), 'Q3': ('07', '09'), 'Q4': ('10', '12')}
            if selected_quarter in quarter_map:
                start_month, end_month = quarter_map[selected_quarter]
                date_conditions += " AND strftime('%m', registered_date) BETWEEN ? AND ?"
                params_base.extend([start_month, end_month])
        
        # Get projects for this engineer with date filters
        if report_type == 'sales':
            query = f"""
                SELECT project_name, MAX(registered_date) as latest_date
                FROM projects 
                WHERE sales_eng = ? AND project_name IS NOT NULL AND project_name != ''
                {date_conditions}
                GROUP BY project_name
                ORDER BY latest_date DESC
            """
        else:
            query = f"""
                SELECT project_name, MAX(registered_date) as latest_date
                FROM projects 
                WHERE presale_eng = ? AND project_name IS NOT NULL AND project_name != ''
                {date_conditions}
                GROUP BY project_name
                ORDER BY latest_date DESC
            """
        c.execute(query, params_base)
        project_names = [row[0] for row in c.fetchall()]
        
        for project_name in project_names:
            # Get quotations for this project by this engineer with date filters
            if report_type == 'sales':
                query = f"""
                    SELECT p.id, p.quote_ref, p.presale_eng, p.status, p.quotation_selling_price, p.registered_date, p.project_name,
                           COALESCE(eu.name, co.name, cn.name, 'N/A') as client_name, rp.client_type, rp.id as register_project_id,
                           rp.end_user_id, rp.contractor_id, rp.consultant_id
                    FROM projects p
                    LEFT JOIN register_project rp ON p.project_name = rp.project_name
                    LEFT JOIN end_users eu ON rp.end_user_id = eu.id
                    LEFT JOIN contractors co ON rp.contractor_id = co.id
                    LEFT JOIN consultants cn ON rp.consultant_id = cn.id
                    WHERE p.project_name = ? AND p.sales_eng = ?
                    {date_conditions.replace('registered_date', 'p.registered_date') if date_conditions else ''}
                    ORDER BY p.registered_date DESC
                """
                params = [project_name, selected_engineer] + params_base[1:]
            else:
                query = f"""
                    SELECT p.id, p.quote_ref, p.sales_eng, p.status, p.quotation_selling_price, p.registered_date, p.project_name,
                           COALESCE(eu.name, co.name, cn.name, 'N/A') as client_name, rp.client_type, rp.id as register_project_id,
                           rp.end_user_id, rp.contractor_id, rp.consultant_id
                    FROM projects p
                    LEFT JOIN register_project rp ON p.project_name = rp.project_name
                    LEFT JOIN end_users eu ON rp.end_user_id = eu.id
                    LEFT JOIN contractors co ON rp.contractor_id = co.id
                    LEFT JOIN consultants cn ON rp.consultant_id = cn.id
                    WHERE p.project_name = ? AND p.presale_eng = ?
                    {date_conditions.replace('registered_date', 'p.registered_date') if date_conditions else ''}
                    ORDER BY p.registered_date DESC
                """
                params = [project_name, selected_engineer] + params_base[1:]
            c.execute(query, params)
            
            quotations = []
            for row in c.fetchall():
                # Determine client_id based on client_type
                client_type = row[8]
                client_id = None
                if client_type == 'End User' and row[10]:
                    client_id = row[10]
                elif client_type == 'Contractor' and row[11]:
                    client_id = row[11]
                elif client_type == 'Consultant' and row[12]:
                    client_id = row[12]
                
                quotations.append({
                    'id': row[0],
                    'quote_ref': row[1],
                    'associated_engineer': row[2],
                    'status': row[3],
                    'selling_price': row[4],
                    'registered_date': row[5],
                    'project_name': row[6],
                    'client_name': row[7],
                    'client_type': client_type,
                    'register_project_id': row[9],
                    'client_id': client_id
                })
            
            if quotations:
                projects.append({
                    'name': project_name,
                    'quotations': quotations
                })
                total_quotations += len(quotations)
    
    # Calculate summary statistics and add status flags to each project
    won_count = 0
    lost_count = 0
    ongoing_count = 0
    total_won_value = 0
    total_lost_value = 0
    total_ongoing_value = 0
    
    for project in projects:
        project_has_won = False
        project_has_lost = False
        project_has_ongoing = False
        
        for q in project['quotations']:
            status = (q['status'] or '').lower()
            selling_price = float(q['selling_price'] or 0)
            # Check for won status variations (Won, Closed Won, etc.)
            if 'won' in status:
                won_count += 1
                total_won_value += selling_price
                project_has_won = True
                q['status_category'] = 'won'
            # Check for lost status variations (Lost, Closed Lost, etc.)
            elif 'lost' in status:
                lost_count += 1
                total_lost_value += selling_price
                project_has_lost = True
                q['status_category'] = 'lost'
            else:
                ongoing_count += 1
                total_ongoing_value += selling_price
                project_has_ongoing = True
                q['status_category'] = 'ongoing'
        
        project['has_won'] = project_has_won
        project['has_lost'] = project_has_lost
        project['has_ongoing'] = project_has_ongoing
    
    summary = {
        'won_count': won_count,
        'lost_count': lost_count,
        'ongoing_count': ongoing_count,
        'total_won_value': total_won_value,
        'total_lost_value': total_lost_value,
        'total_ongoing_value': total_ongoing_value
    }
    
    # Calculate presale/sales engineer statistics (associated engineers)
    associated_stats = []
    if selected_engineer and projects:
        # Collect all associated engineers and their stats
        engineer_data = {}
        for project in projects:
            for q in project['quotations']:
                assoc_eng = q.get('associated_engineer', '') or 'Unassigned'
                if assoc_eng not in engineer_data:
                    engineer_data[assoc_eng] = {'total': 0, 'won': 0, 'lost': 0, 'ongoing': 0, 'won_value': 0, 'lost_value': 0, 'ongoing_value': 0}
                
                engineer_data[assoc_eng]['total'] += 1
                selling_price = float(q.get('selling_price') or 0)
                status_cat = q.get('status_category', 'ongoing')
                
                if status_cat == 'won':
                    engineer_data[assoc_eng]['won'] += 1
                    engineer_data[assoc_eng]['won_value'] += selling_price
                elif status_cat == 'lost':
                    engineer_data[assoc_eng]['lost'] += 1
                    engineer_data[assoc_eng]['lost_value'] += selling_price
                else:
                    engineer_data[assoc_eng]['ongoing'] += 1
                    engineer_data[assoc_eng]['ongoing_value'] += selling_price
        
        # Convert to list and sort by total quotations descending
        for eng_name, stats in engineer_data.items():
            associated_stats.append({
                'name': eng_name,
                'total': stats['total'],
                'won': stats['won'],
                'lost': stats['lost'],
                'ongoing': stats['ongoing'],
                'won_value': stats['won_value'],
                'lost_value': stats['lost_value'],
                'ongoing_value': stats['ongoing_value']
            })
        associated_stats.sort(key=lambda x: x['total'], reverse=True)
    
    conn.close()
    
    return render_template('engineer_reports.html',
                           report_type=report_type,
                           engineers=engineers,
                           selected_engineer=selected_engineer,
                           years=years,
                           selected_year=selected_year,
                           selected_quarter=selected_quarter,
                           selected_month=selected_month,
                           selected_week=selected_week,
                           projects=projects,
                           total_quotations=total_quotations,
                           summary=summary,
                           associated_stats=associated_stats)


@app.route('/export_engineer_report_excel')
@login_required
def export_engineer_report_excel():
    """Export Engineer Report to Excel with professional formatting"""
    from openpyxl import Workbook
    from openpyxl.styles import Font, Fill, PatternFill, Alignment, Border, Side
