@app.route('/rfq_summary', methods=['GET'])
@permission_required('view_rfq')
def rfq_summary():
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()

    # Get user role to conditionally show elements
    user_role = None
    if 'user_id' in session:
        c.execute("SELECT role FROM users WHERE id = ?", (session['user_id'],))
        user_role_result = c.fetchone()
        if user_role_result:
            user_role = user_role_result[0]

    # Get filter values from URL
    filters = {
        'presale_engineer': request.args.get('presale_engineer'),
        'sales_engineer': request.args.get('sales_engineer'),
        'rfq_status': request.args.get('rfq_status'),
        'quotation_status': request.args.get('quotation_status'),
        'start_date': request.args.get('start_date'),
        'end_date': request.args.get('end_date'),
    }

    # Fetch data for filter dropdowns
    c.execute("SELECT DISTINCT sales_engineer_presale FROM rfq_requests")
    presale_engineers = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT sales_engineer_sales FROM rfq_requests")
    sales_engineers = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT rfq_status FROM rfq_requests")
    rfq_status_options = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT quotation_status FROM rfq_requests")
    quotation_status_options = [row[0] for row in c.fetchall()]

    # Base query with LEFT JOIN to get quotation reference
    query = """
        SELECT
            r.id, r.rfq_reference, r.project_name, r.project_status, r.priority,
            r.sales_engineer_presale, r.sales_engineer_sales, r.rfq_status,
            r.quotation_status, r.deadline, r.note, r.requested_time,
            p.quote_ref, r.system
        FROM rfq_requests r
        LEFT JOIN projects p ON r.rfq_reference = p.rfq_reference
        WHERE 1=1
    """
    params = []

    # Apply filters
    if filters['presale_engineer']: query += " AND r.sales_engineer_presale = ?"; params.append(filters['presale_engineer'])
    if filters['sales_engineer']: query += " AND r.sales_engineer_sales = ?"; params.append(filters['sales_engineer'])
    if filters['rfq_status']: query += " AND r.rfq_status = ?"; params.append(filters['rfq_status'])
    if filters['quotation_status']: query += " AND r.quotation_status = ?"; params.append(filters['quotation_status'])
    if filters['start_date']: query += " AND date(r.requested_time) >= ?"; params.append(filters['start_date'])
    if filters['end_date']: query += " AND date(r.requested_time) <= ?"; params.append(filters['end_date'])
    
    query += " ORDER BY r.requested_time DESC"

    c.execute(query, params)
    rfqs = c.fetchall()
    total_rfqs = len(rfqs)

    # Chart data logic that also respects filters
    chart_query = "SELECT rfq_status, COUNT(*) FROM rfq_requests r WHERE 1=1"
    # Re-apply the same parameter logic for the chart query
    if filters['presale_engineer']: chart_query += " AND r.sales_engineer_presale = ?"
    if filters['sales_engineer']: chart_query += " AND r.sales_engineer_sales = ?"
    if filters['rfq_status']: chart_query += " AND r.rfq_status = ?"
    if filters['quotation_status']: chart_query += " AND r.quotation_status = ?"
    if filters['start_date']: chart_query += " AND date(r.requested_time) >= ?"
    if filters['end_date']: chart_query += " AND date(r.requested_time) <= ?"
    chart_query += " GROUP BY r.rfq_status"
    c.execute(chart_query, params) # Use the same params list
    status_counts_raw = c.fetchall()
    conn.close()

    status_labels = [row[0] for row in status_counts_raw]
    status_counts = [row[1] for row in status_counts_raw]
    
    # Calculate KPI statistics
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    # Build same query for statistics
    stats_query_base = "SELECT COUNT(*) FROM rfq_requests r WHERE 1=1"
    stats_params = params.copy()
    filter_clause = ""
    if filters['presale_engineer']: filter_clause += " AND r.sales_engineer_presale = ?"
    if filters['sales_engineer']: filter_clause += " AND r.sales_engineer_sales = ?"
    if filters['rfq_status']: filter_clause += " AND r.rfq_status = ?"
    if filters['quotation_status']: filter_clause += " AND r.quotation_status = ?"
    if filters['start_date']: filter_clause += " AND date(r.requested_time) >= ?"
    if filters['end_date']: filter_clause += " AND date(r.requested_time) <= ?"
    
    # Count by status
    c.execute(stats_query_base + filter_clause + " AND r.rfq_status = 'Queue'", stats_params)
    queue_count = c.fetchone()[0]
    
    c.execute(stats_query_base + filter_clause + " AND r.rfq_status = 'Quoted'", stats_params)
    quoted_count = c.fetchone()[0]
    
    c.execute(stats_query_base + filter_clause + " AND r.rfq_status = 'Cancelled'", stats_params)
    cancelled_count = c.fetchone()[0]
    
    # Count high priority
    c.execute(stats_query_base + filter_clause + " AND r.priority = 'High'", stats_params)
    high_priority_count = c.fetchone()[0]
    
    # Count overdue (deadline passed and still in Queue)
    c.execute(stats_query_base + filter_clause + " AND r.deadline < date('now') AND r.rfq_status = 'Queue'", stats_params)
    overdue_count = c.fetchone()[0]
    
    conn.close()
    
    kpi_stats = {
        'total': total_rfqs,
        'queue': queue_count,
        'quoted': quoted_count,
        'cancelled': cancelled_count,
        'high_priority': high_priority_count,
        'overdue': overdue_count
    }

    return render_template('rfq_summary.html',
                           rfqs=rfqs,
                           total_rfqs=total_rfqs,
                           kpi_stats=kpi_stats,
                           user_role=user_role,
                           presale_engineers=presale_engineers,
                           sales_engineers=sales_engineers,
                           rfq_status_options=rfq_status_options,
                           quotation_status_options=quotation_status_options,
                           status_labels=status_labels,
                           status_counts=status_counts,
                           current_filters=filters)

###################################
# RFQ Engineer Reports - Similar to Engineer Reports but for RFQs
@app.route('/rfq_engineer_reports')
@login_required
def rfq_engineer_reports():
    """RFQ Engineer Reports - View RFQ statistics by Sales or Presale Engineer"""
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    report_type = request.args.get('type', 'sales')
    selected_engineer = request.args.get('engineer', '')
    selected_year = request.args.get('year', '')
    selected_quarter = request.args.get('quarter', '')
    selected_month = request.args.get('month', '')
    selected_week = request.args.get('week', '')
    
    # Get available years from RFQs
    c.execute("SELECT DISTINCT strftime('%Y', requested_time) as year FROM rfq_requests WHERE requested_time IS NOT NULL ORDER BY year DESC")
    years = [row[0] for row in c.fetchall() if row[0]]
    
    # Get list of engineers based on report type
    if report_type == 'sales':
        c.execute("SELECT DISTINCT sales_engineer_sales FROM rfq_requests WHERE sales_engineer_sales IS NOT NULL AND sales_engineer_sales != '' ORDER BY sales_engineer_sales")
    else:
        c.execute("SELECT DISTINCT sales_engineer_presale FROM rfq_requests WHERE sales_engineer_presale IS NOT NULL AND sales_engineer_presale != '' ORDER BY sales_engineer_presale")
    
    engineers = [row[0] for row in c.fetchall()]
    
    rfqs = []
    total_rfqs_count = 0
    
    # Summary statistics
    summary = {
        'queue': 0, 'studying': 0, 'pricing': 0, 'quoted': 0, 'cancelled': 0
    }
    
    # Associated engineers stats (opposite type)
    associated_stats = []
    
    if selected_engineer:
        # Build date filter conditions
        date_conditions = ""
        params_base = [selected_engineer]
        
        if selected_year:
            date_conditions += " AND strftime('%Y', requested_time) = ?"
            params_base.append(selected_year)
        
        if selected_month:
            date_conditions += " AND strftime('%m', requested_time) = ?"
            params_base.append(selected_month)
            
            if selected_week:
                week_num = int(selected_week)
                start_day = (week_num - 1) * 7 + 1
                end_day = week_num * 7
                date_conditions += " AND CAST(strftime('%d', requested_time) AS INTEGER) BETWEEN ? AND ?"
                params_base.extend([start_day, end_day])
        elif selected_quarter:
            quarter_map = {'Q1': ('01', '03'), 'Q2': ('04', '06'), 'Q3': ('07', '09'), 'Q4': ('10', '12')}
            if selected_quarter in quarter_map:
                start_month, end_month = quarter_map[selected_quarter]
                date_conditions += " AND strftime('%m', requested_time) BETWEEN ? AND ?"
                params_base.extend([start_month, end_month])
        
        # Get RFQs for this engineer with date filters
        if report_type == 'sales':
            query = f"""
                SELECT id, rfq_reference, project_name, project_status, priority,
                       sales_engineer_presale, sales_engineer_sales, rfq_status,
                       quotation_status, deadline, note, requested_time, system
                FROM rfq_requests 
                WHERE sales_engineer_sales = ?
                {date_conditions}
                ORDER BY requested_time DESC
            """
        else:
            query = f"""
                SELECT id, rfq_reference, project_name, project_status, priority,
                       sales_engineer_presale, sales_engineer_sales, rfq_status,
                       quotation_status, deadline, note, requested_time, system
                FROM rfq_requests 
                WHERE sales_engineer_presale = ?
                {date_conditions}
                ORDER BY requested_time DESC
            """
        c.execute(query, params_base)
        rfqs_raw = c.fetchall()
        total_rfqs_count = len(rfqs_raw)
        
        # Group RFQs by project name
        projects_dict = {}
        for rfq in rfqs_raw:
            project_name = rfq[2] or 'Unknown Project'
            if project_name not in projects_dict:
                projects_dict[project_name] = {
                    'name': project_name,
                    'rfqs': [],
                    'has_queue': False,
                    'has_studying': False,
                    'has_pricing': False,
                    'has_quoted': False,
                    'has_cancelled': False
                }
            
            status = rfq[7].lower() if rfq[7] else ''
            status_category = 'queue'
            if 'queue' in status:
                status_category = 'queue'
                projects_dict[project_name]['has_queue'] = True
                summary['queue'] += 1
            elif 'study' in status:
                status_category = 'studying'
                projects_dict[project_name]['has_studying'] = True
                summary['studying'] += 1
            elif 'pricing' in status or 'price' in status:
                status_category = 'pricing'
                projects_dict[project_name]['has_pricing'] = True
                summary['pricing'] += 1
            elif 'quoted' in status:
                status_category = 'quoted'
                projects_dict[project_name]['has_quoted'] = True
                summary['quoted'] += 1
            elif 'cancel' in status:
                status_category = 'cancelled'
                projects_dict[project_name]['has_cancelled'] = True
                summary['cancelled'] += 1
            
            # Calculate days remaining until deadline
            days_remaining = None
            deadline_str = rfq[9]
            if deadline_str:
                try:
                    from datetime import datetime, date
                    deadline_date = datetime.strptime(deadline_str, '%Y-%m-%d').date()
                    today = date.today()
                    days_remaining = (deadline_date - today).days
                except:
                    pass
            
            projects_dict[project_name]['rfqs'].append({
                'id': rfq[0],
                'rfq_reference': rfq[1],
                'project_name': rfq[2],
                'project_status': rfq[3],
                'priority': rfq[4],
                'presale_engineer': rfq[5],
                'sales_engineer': rfq[6],
                'rfq_status': rfq[7],
                'quotation_status': rfq[8],
                'deadline': rfq[9],
                'note': rfq[10],
                'requested_time': rfq[11],
                'system': rfq[12],
                'status_category': status_category,
                'associated_engineer': rfq[5] if report_type == 'sales' else rfq[6],
                'days_remaining': days_remaining
            })
        
        # Convert to list and sort by number of RFQs
        projects = list(projects_dict.values())
        projects.sort(key=lambda x: len(x['rfqs']), reverse=True)
        
        # Get associated engineers stats (the opposite type)
        if report_type == 'sales':
            # Get presale engineers who worked on these RFQs
            assoc_query = f"""
                SELECT sales_engineer_presale,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%queue%' THEN 1 ELSE 0 END) as queue_count,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%study%' THEN 1 ELSE 0 END) as studying_count,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%pric%' THEN 1 ELSE 0 END) as pricing_count,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%quoted%' THEN 1 ELSE 0 END) as quoted_count,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%cancel%' THEN 1 ELSE 0 END) as cancelled_count,
                       COUNT(*) as total
                FROM rfq_requests
                WHERE sales_engineer_sales = ? AND sales_engineer_presale IS NOT NULL AND sales_engineer_presale != ''
                {date_conditions}
                GROUP BY sales_engineer_presale
                ORDER BY total DESC
            """
        else:
            # Get sales engineers who worked on these RFQs
            assoc_query = f"""
                SELECT sales_engineer_sales,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%queue%' THEN 1 ELSE 0 END) as queue_count,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%study%' THEN 1 ELSE 0 END) as studying_count,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%pric%' THEN 1 ELSE 0 END) as pricing_count,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%quoted%' THEN 1 ELSE 0 END) as quoted_count,
                       SUM(CASE WHEN LOWER(rfq_status) LIKE '%cancel%' THEN 1 ELSE 0 END) as cancelled_count,
                       COUNT(*) as total
                FROM rfq_requests
                WHERE sales_engineer_presale = ? AND sales_engineer_sales IS NOT NULL AND sales_engineer_sales != ''
                {date_conditions}
                GROUP BY sales_engineer_sales
                ORDER BY total DESC
            """
        c.execute(assoc_query, params_base)
        assoc_rows = c.fetchall()
        for row in assoc_rows:
            associated_stats.append({
                'name': row[0],
                'queue': row[1],
                'studying': row[2],
                'pricing': row[3],
                'quoted': row[4],
                'cancelled': row[5],
                'total': row[6]
            })
    
    conn.close()
    
    # If no engineer selected, projects will be empty list
    if not selected_engineer:
        projects = []
    
    return render_template('rfq_engineer_reports.html',
                           report_type=report_type,
                           engineers=engineers,
                           selected_engineer=selected_engineer,
                           projects=projects,
                           total_rfqs=total_rfqs_count,
                           summary=summary,
                           associated_stats=associated_stats,
                           years=years,
                           selected_year=selected_year,
                           selected_quarter=selected_quarter,
                           selected_month=selected_month,
                           selected_week=selected_week)


@app.route('/export_rfq_engineer_report_excel')
@login_required
def export_rfq_engineer_report_excel():
    """Export RFQ Engineer Report to Excel with professional formatting"""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    from openpyxl.utils import get_column_letter
