@app.route('/technical_support_summary', methods=['GET'])
@login_required
@permission_required('view_rfts')
def technical_support_summary():
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()

    # Get filter parameters from URL
    filters = {
        'request_type': request.args.get('request_type'),
        'request_status': request.args.get('request_status'),
        'priority': request.args.get('priority'),
        'presale_engineer': request.args.get('presale_engineer'),
        'sales_engineer': request.args.get('sales_engineer'),
    }

    # Build the query for requests
    query = "SELECT * FROM technical_support_requests WHERE 1=1"
    params = []
    # (The logic for adding filter conditions to the query remains the same)
    if filters['request_type']: query += " AND request_type = ?"; params.append(filters['request_type'])
    if filters['request_status']: query += " AND request_status = ?"; params.append(filters['request_status'])
    if filters['priority']: query += " AND priority = ?"; params.append(filters['priority'])
    if filters['presale_engineer']: query += " AND presale_engineer = ?"; params.append(filters['presale_engineer'])
    if filters['sales_engineer']: query += " AND sales_engineer = ?"; params.append(filters['sales_engineer'])
    
    # Order by most recent first (by requested_time descending, then by id descending)
    query += " ORDER BY requested_time DESC, id DESC"

    c.execute(query, params)
    requests = c.fetchall()
    total_requests = len(requests)  # Calculate total number of requests

    # Prepare data for the pie chart
    c.execute("SELECT request_status, COUNT(*) FROM technical_support_requests GROUP BY request_status")
    status_counts_raw = c.fetchall()
    
    # Calculate KPI counts for dashboard cards
    c.execute("SELECT COUNT(*) FROM technical_support_requests WHERE LOWER(request_status) = 'done'")
    done_count = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM technical_support_requests WHERE LOWER(request_status) IN ('pending', 'in progress', 'queue', 'studying')")
    pending_count = c.fetchone()[0]
    c.execute("SELECT COUNT(*) FROM technical_support_requests WHERE LOWER(priority) = 'high'")
    high_priority_count = c.fetchone()[0]

    # Fetch distinct values for filtering
    c.execute("SELECT DISTINCT request_type FROM technical_support_requests")
    request_types = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT request_status FROM technical_support_requests")
    request_statuses = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT priority FROM technical_support_requests")
    priorities = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT presale_engineer FROM technical_support_requests")
    presale_engineers = [row[0] for row in c.fetchall()]
    c.execute("SELECT DISTINCT sales_engineer FROM technical_support_requests")
    sales_engineers = [row[0] for row in c.fetchall()]

    conn.close()

    status_labels = [row[0] for row in status_counts_raw]
    status_counts = [row[1] for row in status_counts_raw]

    return render_template('technical_support_summary.html',
                           requests=requests,
                           total_requests=total_requests,
                           done_count=done_count,
                           pending_count=pending_count,
                           high_priority_count=high_priority_count,
                           request_types=request_types,
                           request_statuses=request_statuses,
                           priorities=priorities,
                           presale_engineers=presale_engineers,
                           sales_engineers=sales_engineers,
                           status_labels=status_labels,
                           status_counts=status_counts)


@app.route('/rfts_profile/<int:rfts_id>', methods=['GET'])
@login_required
@permission_required('view_rfts')
def rfts_profile(rfts_id):
    """
    RFTS Profile page showing complete technical support request details,
    process timeline, and related information
    """
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    
    # Get RFTS details
    c.execute("SELECT * FROM technical_support_requests WHERE id = ?", (rfts_id,))
    rfts = c.fetchone()
    
    if not rfts:
        conn.close()
        flash('RFTS not found', 'danger')
        return redirect(url_for('technical_support_summary'))
    
    # Get related project details
    c.execute("""
        SELECT rp.id, rp.project_name, e.username as sales_engineer_name
        FROM register_project rp
        LEFT JOIN engineers e ON CAST(rp.sales_engineer_id AS INTEGER) = e.id
        WHERE rp.project_name = ?
    """, (rfts['project_name'],))
    project = c.fetchone()
    
    # Get related quotations for this project
    c.execute("""
        SELECT quote_ref, system, status, registered_date, quotation_selling_price
        FROM projects 
        WHERE project_name = ?
        ORDER BY registered_date DESC
    """, (rfts['project_name'],))
    quotations = c.fetchall()
    
    # Calculate age in days (from RFTS creation to now)
    age_days = 0
    requested_date = None
    if rfts['requested_time']:
        try:
            requested_date = datetime.strptime(rfts['requested_time'].split(' ')[0], '%Y-%m-%d')
            age_days = (datetime.now() - requested_date).days
        except:
            age_days = 0
    
    # Calculate days until deadline
    days_until_deadline = None
    is_overdue = False
    if rfts['deadline']:
        try:
            deadline_date = datetime.strptime(rfts['deadline'], '%Y-%m-%d')
            days_until_deadline = (deadline_date - datetime.now()).days
            is_overdue = days_until_deadline < 0 and rfts['request_status'] != 'Done'
        except:
            pass
    
    # Get other RFTS for same project
    c.execute("""
        SELECT id, rfts_reference, request_type, request_status, deadline
        FROM technical_support_requests 
        WHERE project_name = ? AND id != ?
        ORDER BY requested_time DESC
    """, (rfts['project_name'], rfts_id))
    related_rfts = c.fetchall()
    
    # Get submitted deliverables for this RFTS
    c.execute("""
        SELECT id, document_type, google_drive_link, document_name, notes, submitted_by, submitted_at
        FROM rfts_deliverables
        WHERE rfts_id = ?
        ORDER BY submitted_at DESC
    """, (rfts_id,))
    deliverables = c.fetchall()
    
    # Get RFTS follow-ups
    c.execute("""
        SELECT * FROM rfts_follow_ups
        WHERE rfts_id = ?
        ORDER BY follow_up_date DESC, created_at DESC
    """, (rfts_id,))
    follow_ups = c.fetchall()
    
    # Get RFTS activity log
    c.execute("""
        SELECT * FROM rfts_activity_log
        WHERE rfts_id = ?
        ORDER BY created_at DESC
        LIMIT 20
    """, (rfts_id,))
    activities = c.fetchall()
    
    # Get vendors and distributors for follow-up form
    c.execute("SELECT id, name FROM vendors ORDER BY name")
    vendors = c.fetchall()
    
    c.execute("SELECT id, name FROM distributors ORDER BY name")
    distributors = c.fetchall()
    
    # Get users for assignment dropdown
    c.execute("SELECT username FROM users ORDER BY username")
    users = [row['username'] for row in c.fetchall()]
    
    # Get current date for overdue checking
    current_date = datetime.now().strftime('%Y-%m-%d')
    
    # Count pending follow-ups
    pending_follow_ups = len([f for f in follow_ups if f['status'] == 'Pending'])
    
    conn.close()
    
    return render_template('rfts_profile.html',
                           rfts=rfts,
                           project=project,
                           quotations=quotations,
                           related_rfts=related_rfts,
                           deliverables=deliverables,
                           age_days=age_days,
                           days_until_deadline=days_until_deadline,
                           is_overdue=is_overdue,
                           follow_ups=follow_ups,
                           activities=activities,
                           vendors=vendors,
                           distributors=distributors,
                           users=users,
                           current_date=current_date,
                           pending_follow_ups=pending_follow_ups)


@app.route('/api/rfts/<int:rfts_id>/deliverable', methods=['POST'])
@login_required
@permission_required('view_rfts')
def add_rfts_deliverable(rfts_id):
    """Add a new deliverable (Google Drive link) to an RFTS"""
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    # Verify RFTS exists
    c.execute("SELECT id FROM technical_support_requests WHERE id = ?", (rfts_id,))
    if not c.fetchone():
        conn.close()
        return jsonify({'success': False, 'error': 'RFTS not found'}), 404
    
    data = request.get_json() if request.is_json else request.form
    
    document_type = data.get('document_type', '').strip()
    google_drive_link = data.get('google_drive_link', '').strip()
    document_name = data.get('document_name', '').strip()
    notes = data.get('notes', '').strip()
    
    if not document_type or not google_drive_link:
        conn.close()
        return jsonify({'success': False, 'error': 'Document type and Google Drive link are required'}), 400
    
    # Insert the deliverable
    c.execute("""
        INSERT INTO rfts_deliverables (rfts_id, document_type, google_drive_link, document_name, notes, submitted_by)
        VALUES (?, ?, ?, ?, ?, ?)
    """, (rfts_id, document_type, google_drive_link, document_name, notes, session.get('username', 'Unknown')))
    
    deliverable_id = c.lastrowid
    conn.commit()
    conn.close()
    
    return jsonify({
        'success': True, 
        'message': 'Deliverable added successfully',
        'deliverable_id': deliverable_id
    })


@app.route('/api/rfts/deliverable/<int:deliverable_id>', methods=['DELETE'])
@login_required
@permission_required('view_rfts')
def delete_rfts_deliverable(deliverable_id):
    """Delete a deliverable from an RFTS"""
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    # Get the deliverable to check if it exists and get rfts_id for redirect
    c.execute("SELECT rfts_id, submitted_by FROM rfts_deliverables WHERE id = ?", (deliverable_id,))
    deliverable = c.fetchone()
    
    if not deliverable:
        conn.close()
        return jsonify({'success': False, 'error': 'Deliverable not found'}), 404
    
    rfts_id = deliverable[0]
    
    # Delete the deliverable
    c.execute("DELETE FROM rfts_deliverables WHERE id = ?", (deliverable_id,))
    conn.commit()
    conn.close()
    
    return jsonify({
        'success': True, 
        'message': 'Deliverable deleted successfully',
        'rfts_id': rfts_id
    })


