@app.route('/client_profile/<client_type>/<int:client_id>')
@login_required
def client_profile(client_type, client_id):
    """Comprehensive client profile page with follow-up tracking"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    # Get client details based on type
    if client_type == 'end_user':
        cursor.execute("""
            SELECT eu.*, e.username as assigned_engineer_name
            FROM end_users eu
            LEFT JOIN engineers e ON eu.assigned_sales_engineer_id = e.id
            WHERE eu.id = ?
        """, (client_id,))
        client = cursor.fetchone()
        client_table = 'end_users'
        projects_query = "SELECT * FROM register_project WHERE end_user_id = ? ORDER BY registered_date DESC"
        edit_url = 'edit_end_user'
        view_url = 'view_end_users'
    elif client_type == 'contractor':
        cursor.execute("""
            SELECT c.*, e.username as assigned_engineer_name
            FROM contractors c
            LEFT JOIN engineers e ON c.assigned_sales_engineer_id = e.id
            WHERE c.id = ?
        """, (client_id,))
        client = cursor.fetchone()
        client_table = 'contractors'
        projects_query = "SELECT * FROM register_project WHERE contractor_id = ? ORDER BY registered_date DESC"
        edit_url = 'edit_contractor'
        view_url = 'view_contractors'
    elif client_type == 'consultant':
        cursor.execute("""
            SELECT c.*, e.username as assigned_engineer_name
            FROM consultants c
            LEFT JOIN engineers e ON c.assigned_sales_engineer_id = e.id
            WHERE c.id = ?
        """, (client_id,))
        client = cursor.fetchone()
        client_table = 'consultants'
        projects_query = "SELECT * FROM register_project WHERE consultant_id = ? ORDER BY registered_date DESC"
        edit_url = 'edit_consultant'
        view_url = 'view_consultants'
    else:
        flash('Invalid client type!', 'danger')
        conn.close()
        return redirect(url_for('view_all_clients'))
    
    if not client:
        flash('Client not found!', 'danger')
        conn.close()
        return redirect(url_for('view_all_clients'))
    
    # Get projects for this client
    cursor.execute(projects_query, (client_id,))
    projects = cursor.fetchall()
    
    # Get follow-ups for this client
    cursor.execute("""
        SELECT * FROM client_follow_ups
        WHERE client_type = ? AND client_id = ?
        ORDER BY follow_up_date DESC, created_at DESC
    """, (client_type, client_id))
    follow_ups = cursor.fetchall()
    
    # Get activity log for this client
    cursor.execute("""
        SELECT * FROM client_activity_log
        WHERE client_type = ? AND client_id = ?
        ORDER BY created_at DESC
        LIMIT 20
    """, (client_type, client_id))
    activities = cursor.fetchall()
    
    # Get quotations for projects associated with this client
    project_names = [p['project_name'] for p in projects]
    quotations = []
    if project_names:
        placeholders = ','.join('?' * len(project_names))
        cursor.execute(f"""
            SELECT * FROM projects
            WHERE project_name IN ({placeholders})
            ORDER BY registered_date DESC
        """, project_names)
        quotations = cursor.fetchall()
    
    # Calculate statistics
    total_projects = len(projects)
    total_quotations = len(quotations)
    total_deal_value = sum(p['deal_value'] or 0 for p in projects)
    pending_follow_ups = len([f for f in follow_ups if f['status'] == 'Pending'])
    
    # Stage breakdown
    stage_counts = {}
    for project in projects:
        stage = project['stage'] if project['stage'] else 'Unknown'
        stage_counts[stage] = stage_counts.get(stage, 0) + 1
    
    # Get sales engineers for assignment
    cursor.execute("SELECT id, username FROM engineers WHERE role IN ('Sales Engineer', 'Technical Team Leader')")
    sales_engineers = cursor.fetchall()
    
    # Get users for assignment dropdown
    cursor.execute("SELECT username FROM users ORDER BY username")
    users = [row['username'] for row in cursor.fetchall()]
    
    conn.close()
    
    # Get current date for overdue checking
    from datetime import datetime
    current_date = datetime.now().strftime('%Y-%m-%d')
    
    return render_template('client_profile.html',
                         client=client,
                         client_type=client_type,
                         client_id=client_id,
                         projects=projects,
                         follow_ups=follow_ups,
                         activities=activities,
                         quotations=quotations,
                         total_projects=total_projects,
                         total_quotations=total_quotations,
                         total_deal_value=total_deal_value,
                         pending_follow_ups=pending_follow_ups,
                         stage_counts=stage_counts,
                         sales_engineers=sales_engineers,
                         users=users,
                         edit_url=edit_url,
                         view_url=view_url,
                         current_date=current_date)


@app.route('/export_client_profile_excel/<client_type>/<int:client_id>')
@login_required
def export_client_profile_excel(client_type, client_id):
    """Export client profile data to Excel"""
    import io
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
    from openpyxl.utils import get_column_letter
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    # Get client details based on type
    table_map = {'end_user': 'end_users', 'contractor': 'contractors', 'consultant': 'consultants'}
    client_table = table_map.get(client_type)
    
    if not client_table:
        flash('Invalid client type!', 'danger')
        return redirect(url_for('view_all_clients'))
    
    cursor.execute(f"""
        SELECT c.*, e.username as assigned_engineer_name
        FROM {client_table} c
        LEFT JOIN engineers e ON c.assigned_sales_engineer_id = e.id
        WHERE c.id = ?
    """, (client_id,))
    client = cursor.fetchone()
    
    if not client:
        flash('Client not found!', 'danger')
        return redirect(url_for('view_all_clients'))
    
    # Get projects with engineer names
    if client_type == 'end_user':
        projects_query = """
            SELECT rp.*, e.name as sales_engineer_name 
            FROM register_project rp
            LEFT JOIN engineers e ON CAST(CAST(rp.sales_engineer_id AS INTEGER) AS TEXT) = CAST(e.id AS TEXT)
            WHERE rp.end_user_id = ? ORDER BY rp.registered_date DESC
        """
    elif client_type == 'contractor':
        projects_query = """
            SELECT rp.*, e.name as sales_engineer_name 
            FROM register_project rp
            LEFT JOIN engineers e ON CAST(CAST(rp.sales_engineer_id AS INTEGER) AS TEXT) = CAST(e.id AS TEXT)
            WHERE rp.contractor_id = ? ORDER BY rp.registered_date DESC
        """
    else:
        projects_query = """
            SELECT rp.*, e.name as sales_engineer_name 
            FROM register_project rp
            LEFT JOIN engineers e ON CAST(CAST(rp.sales_engineer_id AS INTEGER) AS TEXT) = CAST(e.id AS TEXT)
            WHERE rp.consultant_id = ? ORDER BY rp.registered_date DESC
        """
    
    cursor.execute(projects_query, (client_id,))
    projects = cursor.fetchall()
    
    # Get quotations for all projects
    all_quotations = []
    all_rfqs = []
    for proj in projects:
        cursor.execute("""
            SELECT * FROM projects WHERE project_name = ? ORDER BY registered_date DESC
        """, (proj['project_name'],))
        quotations = cursor.fetchall()
        for q in quotations:
            all_quotations.append({'project_name': proj['project_name'], **dict(q)})
        
        cursor.execute("""
            SELECT * FROM rfq_requests WHERE project_name = ? ORDER BY requested_time DESC
        """, (proj['project_name'],))
        rfqs = cursor.fetchall()
        for r in rfqs:
            all_rfqs.append({'project_name': proj['project_name'], **dict(r)})
    
    # Get follow-ups
    cursor.execute("""
        SELECT * FROM client_follow_ups
        WHERE client_type = ? AND client_id = ?
        ORDER BY follow_up_date DESC
    """, (client_type, client_id))
    follow_ups = cursor.fetchall()
    
    conn.close()
    
    # Create workbook
    wb = Workbook()
    ws = wb.active
    ws.title = "Client Profile"
    
    # Styles
    FONT_NAME = 'Calibri'
    header_font = Font(name=FONT_NAME, bold=True, size=14, color='FFFFFF')
    title_font = Font(name=FONT_NAME, bold=True, size=16, color='667eea')
    label_font = Font(name=FONT_NAME, bold=True, size=11)
    value_font = Font(name=FONT_NAME, size=11)
    header_fill = PatternFill(start_color='667eea', end_color='667eea', fill_type='solid')
    alt_fill = PatternFill(start_color='f8f9fa', end_color='f8f9fa', fill_type='solid')
    thin_border = Border(
        left=Side(style='thin'), right=Side(style='thin'),
        top=Side(style='thin'), bottom=Side(style='thin')
    )
    
    # Client Info Section
    ws['A1'] = f"Client Profile: {client['name']}"
    ws['A1'].font = title_font
    ws.merge_cells('A1:D1')
    
    type_labels = {'end_user': 'End User', 'contractor': 'Contractor', 'consultant': 'Consultant'}
    ws['A2'] = f"Type: {type_labels.get(client_type, client_type)}"
    ws['A2'].font = value_font
    
    # Contact Information
    row = 4
    ws[f'A{row}'] = "Contact Information"
    ws[f'A{row}'].font = header_font
    ws[f'A{row}'].fill = header_fill
    ws.merge_cells(f'A{row}:D{row}')
    
    row += 1
    info_fields = [
        ('Company Name', client['name']),
        ('Contact Person', client['contact_person'] if client['contact_person'] else 'N/A'),
        ('Phone', client['phone'] if client['phone'] else 'N/A'),
        ('Email', client['email'] if client['email'] else 'N/A'),
        ('Notes', client['note'] if client['note'] else 'N/A'),
        ('Assigned Engineer', client['assigned_engineer_name'] if client['assigned_engineer_name'] else 'Not Assigned'),
        ('Client Status', 'Client' if client['is_client'] else 'Prospect'),
        ('Tier', client['client_tier'] if client['client_tier'] else 'Standard'),
    ]
    
    for label, value in info_fields:
        ws[f'A{row}'] = label
        ws[f'A{row}'].font = label_font
        ws[f'B{row}'] = str(value) if value else 'N/A'
        ws[f'B{row}'].font = value_font
        row += 1
    
    # Statistics
    row += 1
    ws[f'A{row}'] = "Statistics"
    ws[f'A{row}'].font = header_font
    ws[f'A{row}'].fill = header_fill
    ws.merge_cells(f'A{row}:D{row}')
    
    row += 1
    total_deal_value = sum(p['deal_value'] or 0 for p in projects)
    pending_followups = len([f for f in follow_ups if f['status'] == 'Pending'])
    
    stats = [
        ('Total Projects', len(projects)),
        ('Total Deal Value (SAR)', f"{total_deal_value:,.2f}"),
        ('Pending Follow-ups', pending_followups),
    ]
    
    for label, value in stats:
        ws[f'A{row}'] = label
        ws[f'A{row}'].font = label_font
        ws[f'B{row}'] = str(value)
        ws[f'B{row}'].font = value_font
        row += 1
    
    # Projects Sheet
    if projects:
        ws_projects = wb.create_sheet(title="Projects")
        headers = ['Project Name', 'Stage', 'Deal Value (SAR)', 'Probability', 'Sales Engineer', 'Scope of Work', 'Registered Date']
        
        green_fill = PatternFill(start_color='28a745', end_color='28a745', fill_type='solid')
        for col, header in enumerate(headers, 1):
            cell = ws_projects.cell(row=1, column=col, value=header)
            cell.font = header_font
            cell.fill = green_fill
            cell.alignment = Alignment(horizontal='center')
            cell.border = thin_border
        
        for idx, project in enumerate(projects, 2):
            ws_projects.cell(row=idx, column=1, value=project['project_name']).font = value_font
            ws_projects.cell(row=idx, column=2, value=project['stage'] if project['stage'] else 'N/A').font = value_font
            ws_projects.cell(row=idx, column=3, value=project['deal_value'] if project['deal_value'] else 0).font = value_font
            ws_projects.cell(row=idx, column=4, value=f"{project['probability']}%" if project['probability'] else 'N/A').font = value_font
            ws_projects.cell(row=idx, column=5, value=project['sales_engineer_name'] if project['sales_engineer_name'] else 'N/A').font = value_font
            ws_projects.cell(row=idx, column=6, value=project['scope_of_work'] if project['scope_of_work'] else 'N/A').font = value_font
            ws_projects.cell(row=idx, column=7, value=project['registered_date'] if project['registered_date'] else 'N/A').font = value_font
            
            for col in range(1, 8):
                ws_projects.cell(row=idx, column=col).border = thin_border
                if idx % 2 == 0:
                    ws_projects.cell(row=idx, column=col).fill = alt_fill
        
        for col in range(1, 8):
            ws_projects.column_dimensions[get_column_letter(col)].width = 20
    
    # Quotations Sheet
    if all_quotations:
        ws_quot = wb.create_sheet(title="Quotations")
        quot_headers = ['Project Name', 'Quote Ref', 'System', 'Presale Eng', 'Sales Eng', 'Cost (SAR)', 'Selling Price (SAR)', 'Margin %', 'Status']
        
        blue_fill = PatternFill(start_color='17a2b8', end_color='17a2b8', fill_type='solid')
        for col, header in enumerate(quot_headers, 1):
            cell = ws_quot.cell(row=1, column=col, value=header)
            cell.font = header_font
            cell.fill = blue_fill
            cell.alignment = Alignment(horizontal='center')
            cell.border = thin_border
        
        for idx, q in enumerate(all_quotations, 2):
            ws_quot.cell(row=idx, column=1, value=q.get('project_name', '')).font = value_font
            ws_quot.cell(row=idx, column=2, value=q.get('quote_ref', '')).font = value_font
            ws_quot.cell(row=idx, column=3, value=q.get('system', '')).font = value_font
            ws_quot.cell(row=idx, column=4, value=q.get('presale_eng', '')).font = value_font
            ws_quot.cell(row=idx, column=5, value=q.get('sales_eng', '')).font = value_font
            ws_quot.cell(row=idx, column=6, value=q.get('quotation_cost', 0) or 0).font = value_font
            ws_quot.cell(row=idx, column=7, value=q.get('quotation_selling_price', 0) or 0).font = value_font
            ws_quot.cell(row=idx, column=8, value=f"{q.get('margin', 0) or 0}%").font = value_font
            ws_quot.cell(row=idx, column=9, value=q.get('status', '')).font = value_font
            
            for col in range(1, 10):
                ws_quot.cell(row=idx, column=col).border = thin_border
                if idx % 2 == 0:
                    ws_quot.cell(row=idx, column=col).fill = alt_fill
        
        for col in range(1, 10):
            ws_quot.column_dimensions[get_column_letter(col)].width = 18
    
    # RFQs Sheet
    if all_rfqs:
        ws_rfq = wb.create_sheet(title="RFQs")
        rfq_headers = ['Project Name', 'RFQ Reference', 'Priority', 'Presale Eng', 'Sales Eng', 'RFQ Status', 'Deadline', 'Requested Date']
        
        yellow_fill = PatternFill(start_color='ffc107', end_color='ffc107', fill_type='solid')
        for col, header in enumerate(rfq_headers, 1):
            cell = ws_rfq.cell(row=1, column=col, value=header)
            cell.font = Font(name=FONT_NAME, bold=True, size=14, color='333333')
            cell.fill = yellow_fill
            cell.alignment = Alignment(horizontal='center')
            cell.border = thin_border
        
        for idx, r in enumerate(all_rfqs, 2):
            ws_rfq.cell(row=idx, column=1, value=r.get('project_name', '')).font = value_font
            ws_rfq.cell(row=idx, column=2, value=r.get('rfq_reference', '')).font = value_font
            ws_rfq.cell(row=idx, column=3, value=r.get('priority', '')).font = value_font
            ws_rfq.cell(row=idx, column=4, value=r.get('sales_engineer_presale', '')).font = value_font
            ws_rfq.cell(row=idx, column=5, value=r.get('sales_engineer_sales', '')).font = value_font
            ws_rfq.cell(row=idx, column=6, value=r.get('rfq_status', '')).font = value_font
            ws_rfq.cell(row=idx, column=7, value=r.get('deadline', '')).font = value_font
            ws_rfq.cell(row=idx, column=8, value=r.get('requested_time', '')).font = value_font
            
            for col in range(1, 9):
                ws_rfq.cell(row=idx, column=col).border = thin_border
                if idx % 2 == 0:
                    ws_rfq.cell(row=idx, column=col).fill = alt_fill
        
        for col in range(1, 9):
            ws_rfq.column_dimensions[get_column_letter(col)].width = 18
    
    # Follow-ups Sheet
    if follow_ups:
        ws_followups = wb.create_sheet(title="Follow-ups")
        headers = ['Date', 'Type', 'Status', 'Notes', 'Assigned To', 'Created By']
        
        for col, header in enumerate(headers, 1):
            cell = ws_followups.cell(row=1, column=col, value=header)
            cell.font = header_font
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal='center')
            cell.border = thin_border
        
        for idx, fu in enumerate(follow_ups, 2):
            ws_followups.cell(row=idx, column=1, value=fu['follow_up_date'] if fu['follow_up_date'] else 'N/A').font = value_font
            ws_followups.cell(row=idx, column=2, value=fu['follow_up_type'] if fu['follow_up_type'] else 'N/A').font = value_font
            ws_followups.cell(row=idx, column=3, value=fu['status'] if fu['status'] else 'N/A').font = value_font
            ws_followups.cell(row=idx, column=4, value=fu['notes'] if fu['notes'] else '').font = value_font
            ws_followups.cell(row=idx, column=5, value=fu['assigned_to'] if fu['assigned_to'] else 'N/A').font = value_font
            ws_followups.cell(row=idx, column=6, value=fu['created_by'] if fu['created_by'] else 'N/A').font = value_font
            
            for col in range(1, 7):
                ws_followups.cell(row=idx, column=col).border = thin_border
                if idx % 2 == 0:
                    ws_followups.cell(row=idx, column=col).fill = alt_fill
        
        for col in range(1, 7):
            ws_followups.column_dimensions[get_column_letter(col)].width = 18
    
    # Column widths for main sheet
    ws.column_dimensions['A'].width = 25
    ws.column_dimensions['B'].width = 40
    
    # Save to BytesIO
    output = io.BytesIO()
    wb.save(output)
    output.seek(0)
    
    safe_name = client['name'].replace(' ', '_').replace('/', '-')[:30]
    filename = f"Client_Profile_{safe_name}_{datetime.now().strftime('%Y%m%d')}.xlsx"
    
    return send_file(
        output,
        mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        as_attachment=True,
        download_name=filename
    )


@app.route('/export_client_profile_pptx/<client_type>/<int:client_id>')
@login_required
def export_client_profile_pptx(client_type, client_id):
    """Export client profile data to PowerPoint"""
    import io
    from pptx import Presentation
    from pptx.util import Inches, Pt
    from pptx.dml.color import RGBColor
    from pptx.enum.text import PP_ALIGN, MSO_ANCHOR
    
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    # Get client details based on type
    table_map = {'end_user': 'end_users', 'contractor': 'contractors', 'consultant': 'consultants'}
    client_table = table_map.get(client_type)
    
    if not client_table:
        flash('Invalid client type!', 'danger')
        return redirect(url_for('view_all_clients'))
    
    cursor.execute(f"""
        SELECT c.*, e.username as assigned_engineer_name
        FROM {client_table} c
        LEFT JOIN engineers e ON c.assigned_sales_engineer_id = e.id
        WHERE c.id = ?
    """, (client_id,))
    client = cursor.fetchone()
    
    if not client:
        flash('Client not found!', 'danger')
        return redirect(url_for('view_all_clients'))
    
    # Get projects with engineer names
    if client_type == 'end_user':
        projects_query = """
            SELECT rp.*, e.name as sales_engineer_name 
            FROM register_project rp
            LEFT JOIN engineers e ON CAST(CAST(rp.sales_engineer_id AS INTEGER) AS TEXT) = CAST(e.id AS TEXT)
            WHERE rp.end_user_id = ? ORDER BY rp.registered_date DESC
        """
    elif client_type == 'contractor':
        projects_query = """
            SELECT rp.*, e.name as sales_engineer_name 
            FROM register_project rp
            LEFT JOIN engineers e ON CAST(CAST(rp.sales_engineer_id AS INTEGER) AS TEXT) = CAST(e.id AS TEXT)
            WHERE rp.contractor_id = ? ORDER BY rp.registered_date DESC
        """
    else:
        projects_query = """
            SELECT rp.*, e.name as sales_engineer_name 
            FROM register_project rp
            LEFT JOIN engineers e ON CAST(CAST(rp.sales_engineer_id AS INTEGER) AS TEXT) = CAST(e.id AS TEXT)
            WHERE rp.consultant_id = ? ORDER BY rp.registered_date DESC
        """
    
    cursor.execute(projects_query, (client_id,))
    projects = cursor.fetchall()
    
    # Get quotations for all projects
    all_quotations = []
    all_rfqs = []
    for proj in projects:
        cursor.execute("""
            SELECT * FROM projects WHERE project_name = ? ORDER BY registered_date DESC
        """, (proj['project_name'],))
        quotations = cursor.fetchall()
        for q in quotations:
            all_quotations.append({'project_name': proj['project_name'], **dict(q)})
        
        cursor.execute("""
            SELECT * FROM rfq_requests WHERE project_name = ? ORDER BY requested_time DESC
        """, (proj['project_name'],))
        rfqs = cursor.fetchall()
        for r in rfqs:
            all_rfqs.append({'project_name': proj['project_name'], **dict(r)})
    
    # Get follow-ups
    cursor.execute("""
        SELECT * FROM client_follow_ups
        WHERE client_type = ? AND client_id = ?
        ORDER BY follow_up_date DESC
    """, (client_type, client_id))
    follow_ups = cursor.fetchall()
    
    conn.close()
    
    # Create presentation
    prs = Presentation()
    prs.slide_width = Inches(13.333)
    prs.slide_height = Inches(7.5)
    
    FONT_NAME = 'Calibri'
    
    type_labels = {'end_user': 'End User', 'contractor': 'Contractor', 'consultant': 'Consultant'}
    type_colors = {
        'end_user': RGBColor(17, 153, 142),
        'contractor': RGBColor(240, 147, 251),
        'consultant': RGBColor(79, 172, 254)
    }
    main_color = type_colors.get(client_type, RGBColor(102, 126, 234))
    
    # Slide 1: Title/Overview
    slide_layout = prs.slide_layouts[6]  # Blank
    slide = prs.slides.add_slide(slide_layout)
    
    # Header background
    header = slide.shapes.add_shape(1, Inches(0), Inches(0), Inches(13.333), Inches(2.5))
    header.fill.solid()
    header.fill.fore_color.rgb = main_color
    header.line.fill.background()
    
    # Client Type Badge
    badge = slide.shapes.add_textbox(Inches(0.5), Inches(0.4), Inches(2), Inches(0.4))
    tf = badge.text_frame
    tf.word_wrap = False
    p = tf.paragraphs[0]
    p.text = type_labels.get(client_type, client_type)
    p.font.size = Pt(14)
    p.font.bold = True
    p.font.color.rgb = RGBColor(255, 255, 255)
    p.font.name = FONT_NAME
    
    # Client Name
    title_box = slide.shapes.add_textbox(Inches(0.5), Inches(0.9), Inches(10), Inches(1))
    tf = title_box.text_frame
    tf.word_wrap = True
    p = tf.paragraphs[0]
    p.text = client['name']
    p.font.size = Pt(36)
    p.font.bold = True
    p.font.color.rgb = RGBColor(255, 255, 255)
    p.font.name = FONT_NAME
    
    # Contact & Engineer
    subtitle_box = slide.shapes.add_textbox(Inches(0.5), Inches(1.8), Inches(10), Inches(0.5))
    tf = subtitle_box.text_frame
    p = tf.paragraphs[0]
    contact = client['contact_person'] if client['contact_person'] else 'No contact'
    engineer = client['assigned_engineer_name'] if client['assigned_engineer_name'] else 'Not assigned'
    p.text = f"Contact: {contact}  |  Managed by: {engineer}"
    p.font.size = Pt(16)
    p.font.color.rgb = RGBColor(255, 255, 255)
    p.font.name = FONT_NAME
    
    # Statistics boxes
    total_deal_value = sum(p['deal_value'] or 0 for p in projects)
    pending_followups = len([f for f in follow_ups if f['status'] == 'Pending'])
    
    stats_data = [
        (len(projects), "Total Projects", RGBColor(102, 126, 234)),
        (len(follow_ups), "Follow-ups", RGBColor(17, 153, 142)),
        (f"{total_deal_value:,.0f}", "Deal Value (SAR)", RGBColor(240, 147, 251)),
        (pending_followups, "Pending", RGBColor(79, 172, 254)),
    ]
    
    box_width = 2.8
    box_height = 1.5
    start_x = 0.7
    box_y = 3
    
    for i, (value, label, color) in enumerate(stats_data):
        box = slide.shapes.add_shape(5, Inches(start_x + i * 3.1), Inches(box_y), Inches(box_width), Inches(box_height))
        box.fill.solid()
        box.fill.fore_color.rgb = color
        box.line.fill.background()
        
        # Value
        val_box = slide.shapes.add_textbox(Inches(start_x + i * 3.1), Inches(box_y + 0.3), Inches(box_width), Inches(0.6))
        tf = val_box.text_frame
        p = tf.paragraphs[0]
        p.text = str(value)
        p.font.size = Pt(32)
        p.font.bold = True
        p.font.color.rgb = RGBColor(255, 255, 255)
        p.font.name = FONT_NAME
        p.alignment = PP_ALIGN.CENTER
        
        # Label
        lbl_box = slide.shapes.add_textbox(Inches(start_x + i * 3.1), Inches(box_y + 0.9), Inches(box_width), Inches(0.4))
        tf = lbl_box.text_frame
        p = tf.paragraphs[0]
        p.text = label
        p.font.size = Pt(14)
        p.font.color.rgb = RGBColor(255, 255, 255)
        p.font.name = FONT_NAME
        p.alignment = PP_ALIGN.CENTER
    
    # Contact Information Section
    info_box = slide.shapes.add_textbox(Inches(0.5), Inches(4.8), Inches(6), Inches(2.5))
    tf = info_box.text_frame
    tf.word_wrap = True
    
    p = tf.paragraphs[0]
    p.text = "Contact Information"
    p.font.size = Pt(18)
    p.font.bold = True
    p.font.color.rgb = main_color
    p.font.name = FONT_NAME
    
    info_items = [
        f"Phone: {client['phone'] if client['phone'] else 'N/A'}",
        f"Email: {client['email'] if client['email'] else 'N/A'}",
        f"Notes: {client['note'] if client['note'] else 'N/A'}",
        f"Client Status: {'Client' if client['is_client'] else 'Prospect'}",
        f"Tier: {client['client_tier'] if client['client_tier'] else 'Standard'}",
    ]
    
    for item in info_items:
        p = tf.add_paragraph()
        p.text = item
        p.font.size = Pt(12)
        p.font.color.rgb = RGBColor(80, 80, 80)
        p.font.name = FONT_NAME
        p.space_before = Pt(4)
    
    # Slide 2: Projects Table (if projects exist)
    if projects:
        slide = prs.slides.add_slide(slide_layout)
        
        # Title
        title = slide.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(10), Inches(0.6))
        tf = title.text_frame
        p = tf.paragraphs[0]
        p.text = f"Projects for {client['name']}"
        p.font.size = Pt(28)
        p.font.bold = True
        p.font.color.rgb = main_color
        p.font.name = FONT_NAME
        
        # Projects table
        cols = 5
        rows = min(len(projects) + 1, 12)  # Limit rows
        table = slide.shapes.add_table(rows, cols, Inches(0.5), Inches(1.2), Inches(12.3), Inches(rows * 0.5)).table
        
        headers = ['Project Name', 'Stage', 'Deal Value (SAR)', 'Probability', 'Date']
        col_widths = [4, 2, 2, 2, 2.3]
        
        for i, (header, width) in enumerate(zip(headers, col_widths)):
            table.columns[i].width = Inches(width)
            cell = table.cell(0, i)
            cell.text = header
            cell.fill.solid()
            cell.fill.fore_color.rgb = main_color
            for para in cell.text_frame.paragraphs:
                para.font.bold = True
                para.font.size = Pt(11)
                para.font.color.rgb = RGBColor(255, 255, 255)
                para.font.name = FONT_NAME
                para.alignment = PP_ALIGN.CENTER
            cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        for idx, proj in enumerate(projects[:rows-1], 1):
            data = [
                proj['project_name'][:40] if proj['project_name'] else 'N/A',
                proj['stage'] if proj['stage'] else 'N/A',
                f"{proj['deal_value'] if proj['deal_value'] else 0:,.0f}",
                proj['probability'] if proj['probability'] else 'N/A',
                proj['registered_date'] if proj['registered_date'] else 'N/A',
            ]
            for col, val in enumerate(data):
                cell = table.cell(idx, col)
                cell.text = str(val)
                if idx % 2 == 0:
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(240, 245, 255)
                for para in cell.text_frame.paragraphs:
                    para.font.size = Pt(10)
                    para.font.name = FONT_NAME
                    para.alignment = PP_ALIGN.CENTER
                cell.vertical_anchor = MSO_ANCHOR.MIDDLE
    
    # Slide 3: Follow-ups (if exist)
    if follow_ups:
        slide = prs.slides.add_slide(slide_layout)
        
        title = slide.shapes.add_textbox(Inches(0.5), Inches(0.3), Inches(10), Inches(0.6))
        tf = title.text_frame
        p = tf.paragraphs[0]
        p.text = f"Follow-ups for {client['name']}"
        p.font.size = Pt(28)
        p.font.bold = True
        p.font.color.rgb = main_color
        p.font.name = FONT_NAME
        
        cols = 5
        rows = min(len(follow_ups) + 1, 12)
        table = slide.shapes.add_table(rows, cols, Inches(0.5), Inches(1.2), Inches(12.3), Inches(rows * 0.5)).table
        
        headers = ['Date', 'Type', 'Status', 'Notes', 'Assigned To']
        col_widths = [2, 2, 2, 4, 2.3]
        
        for i, (header, width) in enumerate(zip(headers, col_widths)):
            table.columns[i].width = Inches(width)
            cell = table.cell(0, i)
            cell.text = header
            cell.fill.solid()
            cell.fill.fore_color.rgb = main_color
            for para in cell.text_frame.paragraphs:
                para.font.bold = True
                para.font.size = Pt(11)
                para.font.color.rgb = RGBColor(255, 255, 255)
                para.font.name = FONT_NAME
                para.alignment = PP_ALIGN.CENTER
            cell.vertical_anchor = MSO_ANCHOR.MIDDLE
        
        for idx, fu in enumerate(follow_ups[:rows-1], 1):
            data = [
                fu['follow_up_date'] if fu['follow_up_date'] else 'N/A',
                fu['follow_up_type'] if fu['follow_up_type'] else 'N/A',
                fu['status'] if fu['status'] else 'N/A',
                (fu['notes'] if fu['notes'] else '')[:50],
                fu['assigned_to'] if fu['assigned_to'] else 'N/A',
            ]
            for col, val in enumerate(data):
                cell = table.cell(idx, col)
                cell.text = str(val)
                if idx % 2 == 0:
                    cell.fill.solid()
                    cell.fill.fore_color.rgb = RGBColor(240, 245, 255)
                for para in cell.text_frame.paragraphs:
                    para.font.size = Pt(10)
                    para.font.name = FONT_NAME
                    para.alignment = PP_ALIGN.CENTER
                cell.vertical_anchor = MSO_ANCHOR.MIDDLE
    
    # Save to BytesIO
    output = io.BytesIO()
    prs.save(output)
    output.seek(0)
    
    safe_name = client['name'].replace(' ', '_').replace('/', '-')[:30]
    filename = f"Client_Profile_{safe_name}_{datetime.now().strftime('%Y%m%d')}.pptx"
    
    return send_file(
        output,
        mimetype='application/vnd.openxmlformats-officedocument.presentationml.presentation',
        as_attachment=True,
        download_name=filename
    )


def get_client_name(cursor, client_type, client_id):
    """Helper function to get client name based on type"""
    table_map = {
        'end_user': 'end_users',
        'contractor': 'contractors', 
        'consultant': 'consultants'
    }
    table = table_map.get(client_type.lower().replace(' ', '_'))
    if table:
        cursor.execute(f"SELECT name FROM {table} WHERE id = ?", (client_id,))
        result = cursor.fetchone()
        return result[0] if result else 'Unknown Client'
    return 'Unknown Client'


def get_rfq_info(cursor, rfq_id):
    """Helper function to get RFQ reference number and project name"""
    cursor.execute("""
        SELECT rfq_reference, project_name 
        FROM rfq_requests 
        WHERE id = ?
    """, (rfq_id,))
    result = cursor.fetchone()
    if result:
        ref = result[0] if result[0] else f'RFQ-{rfq_id}'
        project = result[1] if result[1] else 'Unknown Project'
        return ref, project
    return f'RFQ-{rfq_id}', 'Unknown Project'


def get_rfts_info(cursor, rfts_id):
    """Helper function to get RFTS reference number and project name"""
    cursor.execute("""
        SELECT project_name 
        FROM projects 
        WHERE id = ?
    """, (rfts_id,))
    result = cursor.fetchone()
    if result:
        project = result[0] if result[0] else 'Unknown Project'
        return f'RFTS-{rfts_id}', project
    return f'RFTS-{rfts_id}', 'Unknown Project'


def create_task_from_follow_up(cursor, follow_up_id, client_type, client_id, client_name, 
                                subject, notes, follow_up_date, priority, assigned_to, created_by):
    """Create a task record linked to a client follow-up"""
    cursor.execute("SELECT id FROM users WHERE username = ?", (assigned_to,))
    assigned_user = cursor.fetchone()
    assigned_to_id = assigned_user[0] if assigned_user else None
    
    cursor.execute("SELECT id FROM users WHERE username = ?", (created_by,))
    creator = cursor.fetchone()
    assigned_by_id = creator[0] if creator else None
    
    if not assigned_to_id:
        print(f"Warning: Cannot create task for follow-up {follow_up_id} - assigned user '{assigned_to}' not found")
        return None
    
    task_title = f"[Follow-up] {subject}"
    task_description = f"Client: {client_name} ({client_type})\n{notes}" if notes else f"Client: {client_name} ({client_type})"
    
    cursor.execute("""
        INSERT INTO tasks 
        (title, description, assigned_to_id, due_date, priority, assigned_by_id, 
         created_at, status, source_type, source_id, client_name, client_type)
        VALUES (?, ?, ?, ?, ?, ?, datetime('now'), 'To Do', 'client_follow_up', ?, ?, ?)
    """, (task_title, task_description, assigned_to_id, follow_up_date, priority, 
          assigned_by_id, follow_up_id, client_name, client_type))
    
    return cursor.lastrowid


def sync_follow_up_to_task(cursor, follow_up_id, new_status, source_type='client_follow_up'):
    """Sync follow-up status to linked task"""
    status_map = {
        'Pending': 'To Do',
        'Completed': 'Done',
        'Cancelled': 'Done'
    }
    task_status = status_map.get(new_status, 'To Do')
    
    cursor.execute("""
        UPDATE tasks SET status = ?
        WHERE source_type = ? AND source_id = ?
    """, (task_status, source_type, follow_up_id))


