@app.route('/view_projects')
@login_required
@permission_required('view_projects')
def view_projects():
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()

    # Get filter values
    sales_engineer_filter = request.args.get('sales_engineer_id')
    start_date_filter = request.args.get('start_date')
    end_date_filter = request.args.get('end_date')
    project_name_filter = request.args.get('project_name', '').strip()
    stage_filter = request.args.get('stage', '').strip()
    
    # Define stage options for the filter dropdown
    stage_options = [
        'Lead', 'Prospecting', 'Qualification', 'Proposal Prep', 'Proposal Sent',
        'Customer Pending', 'Technical Discussion', 'Negotiation', 'Closed Won', 'Closed Lost'
    ]

    # Smart filter: Fetch only sales engineers who have registered projects
    c.execute("""
        SELECT DISTINCT e.id, e.username 
        FROM engineers e
        INNER JOIN register_project rp ON e.id = rp.sales_engineer_id
        WHERE e.role IN ('Sales Engineer', 'Technical Team Leader', 'General Manager', 'Project Manager', 'Implementation Engineer')
        AND rp.approval_status = 'Approved'
        ORDER BY e.username
    """)
    sales_engineers = c.fetchall()

    # Base query updated to fetch contractor and consultant names - only show approved projects
    query = '''
        SELECT 
            rp.id, rp.project_name, eu.name AS end_user, rp.stage,
            rp.deal_value, rp.probability, rp.expected_close_date,
            en.username AS sales_engineer, rp.registered_date,
            rp.scope_of_work, rp.note,
            co.name as contractor, cn.name as consultant, rp.client_type
        FROM register_project rp
        LEFT JOIN end_users eu ON rp.end_user_id = eu.id
        LEFT JOIN contractors co ON rp.contractor_id = co.id
        LEFT JOIN consultants cn ON rp.consultant_id = cn.id
        LEFT JOIN engineers en ON rp.sales_engineer_id = en.id
        WHERE rp.approval_status = 'Approved'
    '''
    params = []
    user_role = None

    # --- ACCESS CONTROL LOGIC ---
    # Sales Engineers: See only their own projects
    # All other roles (GM, TTL, PM, Project Coordinator, etc.): See ALL projects
    sales_engineer_id = None
    if 'user_id' in session:
        c.execute("SELECT role FROM users WHERE id = ?", (session['user_id'],))
        user_role_result = c.fetchone()
        if user_role_result:
            user_role = user_role_result[0]
            if user_role == 'Sales Engineer':
                # If user is a Sales Engineer, find their engineer ID (case-insensitive)
                c.execute("SELECT id FROM engineers WHERE LOWER(username) = LOWER(?)", (session['username'],))
                engineer_id_result = c.fetchone()
                if engineer_id_result:
                    sales_engineer_id = engineer_id_result[0]
                    # Filter the main query by their ID
                    query += " AND rp.sales_engineer_id = ?"
                    params.append(sales_engineer_id)
                else:
                    # Sales Engineer not found in engineers table - show NO projects for security
                    # Use an impossible condition to return empty result
                    query += " AND 1 = 0"

    # Add other filters if they exist
    if sales_engineer_filter and user_role != 'Sales Engineer':
        query += " AND rp.sales_engineer_id = ?"
        params.append(sales_engineer_filter)
    if start_date_filter:
        query += " AND date(rp.registered_date) >= ?"
        params.append(start_date_filter)
    if end_date_filter:
        query += " AND date(rp.registered_date) <= ?"
        params.append(end_date_filter)
    if project_name_filter:
        query += " AND rp.project_name LIKE ?"
        params.append(f'%{project_name_filter}%')
    if stage_filter and stage_filter in stage_options:
        query += " AND rp.stage = ?"
        params.append(stage_filter)

    # Order by registered date - newest first
    query += " ORDER BY rp.registered_date DESC"
    
    c.execute(query, params)
    projects = c.fetchall()
    conn.close()

    return render_template('view_projects.html',
                           projects=projects,
                           sales_engineers=sales_engineers,
                           user_role=user_role,
                           stage_options=stage_options,
                           current_filters={
                               'sales_engineer_id': sales_engineer_filter,
                               'start_date': start_date_filter,
                               'end_date': end_date_filter,
                               'project_name': project_name_filter,
                               'stage': stage_filter
                           })
