@login_required
def end_user_contractors(end_user_id):
    conn = sqlite3.connect('ProjectStatus.db')
    c = conn.cursor()
    
    # Get end user details
    c.execute('SELECT id, name FROM end_users WHERE id = ?', (end_user_id,))
    end_user = c.fetchone()
    
    if not end_user:
        conn.close()
        flash('End user not found.', 'danger')
