@app.route('/po_profile/<po_request_number>', methods=['GET'])
@login_required
def po_profile(po_request_number):
    """Comprehensive PO Profile page with delivery tracking"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    cursor.execute("""
        SELECT 
            po.*,
            rp.project_name as project_name_actual,
            d.name as distributor_name,
            v.name as vendor_name,
            e.name as presale_engineer_name,
            pm.name as project_manager_name
        FROM purchase_orders po
        LEFT JOIN register_project rp ON CAST(po.project_name AS INTEGER) = rp.id
        LEFT JOIN distributors d ON CAST(po.distributor AS INTEGER) = d.id
        LEFT JOIN vendors v ON CAST(po.vendor AS INTEGER) = v.id
        LEFT JOIN engineers e ON po.presale_engineer = e.username
        LEFT JOIN engineers pm ON po.project_manager = pm.username
        WHERE po.po_request_number = ?
    """, (po_request_number,))
    po = cursor.fetchone()
    
    if not po:
        flash('Purchase Order not found!', 'danger')
        conn.close()
        return redirect(url_for('view_po_status'))
    
    po_number = po['po_number']
    
    cursor.execute("""
        SELECT * FROM po_items 
        WHERE po_number = ? 
        ORDER BY item_number ASC
    """, (po_number,))
    po_items = cursor.fetchall()
    
    cursor.execute("""
        SELECT * FROM purchase_order_monitoring 
        WHERE (po_number = ? OR po_number = ?) AND deleted_at IS NULL
        ORDER BY order_date DESC
    """, (po_number, po_request_number))
    delivery_notes = cursor.fetchall()
    
    cursor.execute("""
        SELECT * FROM vat_invoices 
        WHERE po_request_number = ?
        ORDER BY uploaded_at DESC
    """, (po_request_number,))
    vat_invoices = cursor.fetchall()
    
    # Fetch follow-ups for this PO
    cursor.execute("""
        SELECT * FROM po_follow_ups 
        WHERE po_id = ?
        ORDER BY 
            CASE WHEN status = 'Pending' THEN 0 ELSE 1 END,
            follow_up_date ASC
    """, (po['id'],))
    follow_ups = cursor.fetchall()
    
    # Fetch activity log for this PO
    cursor.execute("""
        SELECT * FROM po_activity_log 
        WHERE po_id = ?
        ORDER BY created_at DESC
    """, (po['id'],))
    activities = cursor.fetchall()
    
    # Get current date for overdue detection
    current_date = datetime.now().strftime('%Y-%m-%d')
    
    # Get users for assignment dropdown
    cursor.execute("SELECT username FROM users ORDER BY username")
    users = [row['username'] for row in cursor.fetchall()]
    
    delivered_count = sum(1 for item in po_items if item['delivery_status'] == 'Delivered')
    partial_count = sum(1 for item in po_items if item['delivery_status'] == 'Partial')
    not_delivered_count = sum(1 for item in po_items if item['delivery_status'] == 'Not Delivered')
    
    conn.close()
    
    return render_template('po_profile.html',
                           po=po,
                           po_number=po_number,
                           po_request_number=po_request_number,
                           po_items=po_items,
                           delivery_notes=delivery_notes,
                           vat_invoices=vat_invoices,
                           follow_ups=follow_ups,
                           activities=activities,
                           current_date=current_date,
                           users=users,
                           delivered_count=delivered_count,
                           partial_count=partial_count,
                           not_delivered_count=not_delivered_count)


@app.route('/add_po_item/<po_number>', methods=['POST'])
@login_required
def add_po_item(po_number):
    """Add new item to PO with comprehensive validation"""
    conn = sqlite3.connect('ProjectStatus.db')
    cursor = conn.cursor()
    
    try:
        part_number = request.form.get('part_number', '').strip()
        
        description = request.form.get('description', '').strip()
        if not description:
            flash('Description is required!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        quantity_str = request.form.get('quantity', '').strip()
        if not quantity_str:
            flash('Quantity is required!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        try:
            quantity = float(quantity_str)
            if quantity <= 0:
                flash('Quantity must be greater than zero!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_number=po_number))
        except (ValueError, TypeError):
            flash('Invalid quantity value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        unit_price_str = request.form.get('unit_price', '0').strip()
        try:
            unit_price = float(unit_price_str) if unit_price_str else 0
            if unit_price < 0:
                flash('Unit price cannot be negative!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_number=po_number))
        except (ValueError, TypeError):
            flash('Invalid unit price value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        total_price_str = request.form.get('total_price', '0').strip()
        try:
            total_price = float(total_price_str) if total_price_str else 0
            if total_price < 0:
                flash('Total price cannot be negative!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_number=po_number))
        except (ValueError, TypeError):
            flash('Invalid total price value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        if total_price == 0 and unit_price > 0:
            total_price = quantity * unit_price
        
        notes = request.form.get('notes', '').strip()
        
        cursor.execute("""
            SELECT COALESCE(MAX(item_number), 0) + 1 
            FROM po_items 
            WHERE po_number = ?
        """, (po_number,))
        next_item_number = cursor.fetchone()[0]
        
        cursor.execute("""
            INSERT INTO po_items (
                po_number, item_number, part_number, description, 
                quantity, unit_price, total_price, notes
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        """, (po_number, next_item_number, part_number, description, 
              quantity, unit_price, total_price, notes))
        
        conn.commit()
        flash('Item added successfully!', 'success')
        
    except KeyError as e:
        flash(f'Missing required field: {str(e)}', 'danger')
    except Exception as e:
        flash(f'Error adding item: {str(e)}', 'danger')
    finally:
        conn.close()
    
    return redirect(url_for('po_profile', po_number=po_number))


@app.route('/edit_po_item/<int:item_id>', methods=['POST'])
@login_required
def edit_po_item(item_id):
    """Edit existing PO item with comprehensive validation"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    cursor.execute("SELECT po_number FROM po_items WHERE id = ?", (item_id,))
    result = cursor.fetchone()
    
    if not result:
        flash('Item not found!', 'danger')
        conn.close()
        return redirect(url_for('view_po_status'))
    
    po_number = result['po_number']
    
    try:
        part_number = request.form.get('part_number', '').strip()
        
        description = request.form.get('description', '').strip()
        if not description:
            flash('Description is required!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        quantity_str = request.form.get('quantity', '').strip()
        if not quantity_str:
            flash('Quantity is required!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        try:
            quantity = float(quantity_str)
            if quantity <= 0:
                flash('Quantity must be greater than zero!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_number=po_number))
        except (ValueError, TypeError):
            flash('Invalid quantity value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        unit_price_str = request.form.get('unit_price', '0').strip()
        try:
            unit_price = float(unit_price_str) if unit_price_str else 0
            if unit_price < 0:
                flash('Unit price cannot be negative!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_number=po_number))
        except (ValueError, TypeError):
            flash('Invalid unit price value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        quantity_delivered_str = request.form.get('quantity_delivered', '0').strip()
        try:
            quantity_delivered = float(quantity_delivered_str) if quantity_delivered_str else 0
            if quantity_delivered < 0:
                flash('Quantity delivered cannot be negative!', 'danger')
                conn.close()
                return redirect(url_for('po_profile', po_number=po_number))
        except (ValueError, TypeError):
            flash('Invalid quantity delivered value!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        delivery_status = request.form.get('delivery_status', 'Not Delivered')
        if delivery_status not in ['Not Delivered', 'Partial', 'Delivered']:
            flash('Invalid delivery status!', 'danger')
            conn.close()
            return redirect(url_for('po_profile', po_number=po_number))
        
        delivery_date = request.form.get('delivery_date', '').strip()
        notes = request.form.get('notes', '').strip()
        
        total_price = quantity * unit_price if unit_price > 0 else 0
        
        if quantity_delivered >= quantity:
            delivery_status = 'Delivered'
        elif quantity_delivered > 0:
            delivery_status = 'Partial'
        else:
            delivery_status = 'Not Delivered'
        
        cursor.execute("""
            UPDATE po_items SET
                part_number = ?,
                description = ?,
                quantity = ?,
                unit_price = ?,
                total_price = ?,
                quantity_delivered = ?,
                delivery_status = ?,
                delivery_date = ?,
                notes = ?,
                updated_at = CURRENT_TIMESTAMP
            WHERE id = ?
        """, (part_number, description, quantity, unit_price, total_price,
              quantity_delivered, delivery_status, delivery_date or None, notes, item_id))
        
        conn.commit()
        flash('Item updated successfully!', 'success')
        
    except KeyError as e:
        flash(f'Missing required field: {str(e)}', 'danger')
    except Exception as e:
        flash(f'Error updating item: {str(e)}', 'danger')
    finally:
        conn.close()
    
    return redirect(url_for('po_profile', po_number=po_number))


@app.route('/delete_po_item/<int:item_id>', methods=['POST'])
@login_required
def delete_po_item(item_id):
    """Delete PO item"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    cursor.execute("SELECT po_number FROM po_items WHERE id = ?", (item_id,))
    result = cursor.fetchone()
    
    if not result:
        flash('Item not found!', 'danger')
        conn.close()
        return redirect(url_for('view_po_status'))
    
    po_number = result['po_number']
    
    cursor.execute("DELETE FROM po_items WHERE id = ?", (item_id,))
    
    conn.commit()
    conn.close()
    
    flash('Item deleted successfully!', 'success')
    return redirect(url_for('po_profile', po_number=po_number))


@app.route('/update_po_vat/<po_number>', methods=['POST'])
@login_required
def update_po_vat(po_number):
    """Update VAT percentage for PO"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    vat_percentage = float(request.form['vat_percentage'])
    
    cursor.execute("SELECT total_amount FROM purchase_orders WHERE po_number = ?", (po_number,))
    result = cursor.fetchone()
    
    if not result:
        flash('Purchase Order not found!', 'danger')
        conn.close()
        return redirect(url_for('view_po_status'))
    
    total_amount = result['total_amount']
    vat_amount = total_amount * (vat_percentage / 100)
    total_with_vat = total_amount + vat_amount
    
    cursor.execute("""
        UPDATE purchase_orders SET
            vat_percentage = ?,
            vat_amount = ?,
            total_with_vat = ?
        WHERE po_number = ?
    """, (vat_percentage, vat_amount, total_with_vat, po_number))
    
    conn.commit()
    conn.close()
    
    flash('VAT updated successfully!', 'success')
    return redirect(url_for('po_profile', po_number=po_number))


@app.route('/import_po_items_excel/<po_request_number>', methods=['POST'])
@login_required
def import_po_items_excel(po_request_number):
    """Import PO items from Excel file"""
    if 'excel_file' not in request.files:
        flash('No file uploaded!', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    file = request.files['excel_file']
    
    if file.filename == '':
        flash('No file selected!', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    if not file.filename.endswith('.xlsx'):
        flash('Invalid file format! Please upload an Excel file (.xlsx only)', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))
    
    try:
        import openpyxl
        from io import BytesIO
        
        file_content = BytesIO(file.read())
        workbook = openpyxl.load_workbook(file_content)
        sheet = workbook.active
        
        conn = sqlite3.connect('ProjectStatus.db')
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT po_number, distributor, system
            FROM purchase_orders WHERE po_request_number = ?
        """, (po_request_number,))
        result = cursor.fetchone()
        po_number = result[0] if result and result[0] else po_request_number
        distributor_name = result[1] if result else None
        po_system = result[2] if result else None
        
        # Get distributor_id from distributors table if distributor name exists
        distributor_id = None
        if distributor_name:
            cursor.execute("SELECT id FROM distributors WHERE name = ?", (distributor_name,))
            dist_result = cursor.fetchone()
            distributor_id = dist_result[0] if dist_result else None
        
        cursor.execute("""
            SELECT COALESCE(MAX(item_number), 0) 
            FROM po_items 
            WHERE po_number = ?
        """, (po_number,))
        next_item_number = cursor.fetchone()[0] + 1
        
        # Get or create a default supplier quotation for PO imports
        cursor.execute("""
            SELECT id FROM supplier_quotations 
            WHERE filename = 'PO Import' AND system = 'PO Import'
            LIMIT 1
        """)
        sq_result = cursor.fetchone()
        
        if sq_result:
            supplier_quotation_id = sq_result[0]
        else:
            cursor.execute("""
                INSERT INTO supplier_quotations 
                (quote_ref, system, filename, quotation_file, uploaded_by, uploaded_at)
                VALUES ('PO-IMPORT', 'PO Import', 'PO Import', X'00', ?, CURRENT_TIMESTAMP)
            """, (session.get('username'),))
            supplier_quotation_id = cursor.lastrowid
        
        items_added = 0
        items_updated = 0
        errors = []
        price_changes = []  # Track price changes during import
        
        for row_idx, row in enumerate(sheet.iter_rows(min_row=2, values_only=True), start=2):
            try:
                if not row or all(cell is None or str(cell).strip() == '' for cell in row):
                    continue
                
                part_number = str(row[0]).strip() if row[0] else ''
                description = str(row[1]).strip() if row[1] else ''
                
                if not description:
                    errors.append(f"Row {row_idx}: Description is required")
                    continue
                
                try:
                    quantity = float(row[2]) if row[2] else 0
                    if quantity <= 0:
                        errors.append(f"Row {row_idx}: Quantity must be greater than zero")
                        continue
                except (ValueError, TypeError):
                    errors.append(f"Row {row_idx}: Invalid quantity value")
                    continue
                
                try:
                    unit_price = float(row[3]) if row[3] else 0
                    if unit_price < 0:
                        errors.append(f"Row {row_idx}: Unit price cannot be negative")
                        continue
                except (ValueError, TypeError):
                    errors.append(f"Row {row_idx}: Invalid unit price value")
                    continue
                
                # Always calculate total as Qty * Unit Price (ignore Excel value)
                total_price = quantity * unit_price
                
                quantity_delivered_provided = False
                quantity_delivered = 0
                
                try:
                    if len(row) > 5 and row[5] is not None and str(row[5]).strip() != '':
                        quantity_delivered = float(row[5])
                        if quantity_delivered < 0:
                            quantity_delivered = 0
                        else:
                            quantity_delivered_provided = True
                except (ValueError, TypeError, IndexError):
                    pass
                
                existing_item = None
                
                if part_number:
                    cursor.execute("""
                        SELECT id, quantity_delivered, delivery_status FROM po_items 
                        WHERE po_number = ? AND LOWER(TRIM(part_number)) = LOWER(TRIM(?))
                    """, (po_number, part_number))
                    existing_item = cursor.fetchone()
                
                if not existing_item:
                    cursor.execute("""
                        SELECT id, quantity_delivered, delivery_status FROM po_items 
                        WHERE po_number = ? AND LOWER(TRIM(description)) = LOWER(TRIM(?))
                    """, (po_number, description))
                    existing_item = cursor.fetchone()
                
                if existing_item:
                    existing_qty_delivered = existing_item[1] or 0
                    existing_delivery_status = existing_item[2] or 'Not Delivered'
                    
                    if quantity_delivered_provided:
                        if quantity_delivered >= quantity:
                            final_delivery_status = 'Delivered'
                        elif quantity_delivered > 0:
                            final_delivery_status = 'Partial'
                        else:
                            final_delivery_status = 'Not Delivered'
                        final_qty_delivered = quantity_delivered
                    else:
                        final_delivery_status = existing_delivery_status
                        final_qty_delivered = existing_qty_delivered
                    
                    cursor.execute("""
                        UPDATE po_items SET
                            part_number = ?,
                            description = ?,
                            quantity = ?,
                            unit_price = ?,
                            total_price = ?,
                            quantity_delivered = ?,
                            delivery_status = ?,
                            updated_at = CURRENT_TIMESTAMP
                        WHERE id = ?
                    """, (part_number, description, quantity, unit_price, total_price, 
                          final_qty_delivered, final_delivery_status, existing_item[0]))
                    items_updated += 1
                    
                    # Check if product exists in quotation_products, if not add it
                    cursor.execute("""
                        SELECT id, unit_price FROM quotation_products 
                        WHERE po_number = ? AND (
                            LOWER(TRIM(part_number)) = LOWER(TRIM(?)) OR
                            LOWER(TRIM(description)) = LOWER(TRIM(?))
                        )
                    """, (po_number, part_number, description))
                    existing_qp = cursor.fetchone()
                    
                    if existing_qp:
                        # Check for price change and log it
                        old_price = existing_qp[1] or 0
                        if old_price != unit_price and part_number:
                            price_change = unit_price - old_price
                            price_change_percent = (price_change / old_price * 100) if old_price > 0 else 0
                            cursor.execute("""
                                INSERT INTO product_price_history 
                                (part_number, old_price, new_price, price_change, price_change_percent, 
                                 currency, supplier_name, po_number, source, changed_by)
                                VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'PO Import Update', ?)
                            """, (part_number, old_price, unit_price, price_change, price_change_percent,
                                  distributor_name, po_number, session.get('username')))
                            # Track this price change for alert
                            price_changes.append({
                                'part_number': part_number,
                                'description': description[:50],
                                'old_price': old_price,
                                'new_price': unit_price,
                                'change': price_change,
                                'change_percent': price_change_percent
                            })
                            # Update the price in quotation_products
                            cursor.execute("""
                                UPDATE quotation_products SET unit_price = ? WHERE id = ?
                            """, (unit_price, existing_qp[0]))
                    else:
                        # Check if same part_number exists with different price (from another source)
                        if part_number:
                            cursor.execute("""
                                SELECT unit_price FROM quotation_products 
                                WHERE LOWER(TRIM(part_number)) = LOWER(TRIM(?))
                                ORDER BY added_at DESC LIMIT 1
                            """, (part_number,))
                            prev_price_row = cursor.fetchone()
                            if prev_price_row and prev_price_row[0] != unit_price:
                                old_price = prev_price_row[0]
                                price_change = unit_price - old_price
                                price_change_percent = (price_change / old_price * 100) if old_price > 0 else 0
                                cursor.execute("""
                                    INSERT INTO product_price_history 
                                    (part_number, old_price, new_price, price_change, price_change_percent, 
                                     currency, supplier_name, po_number, source, changed_by)
                                    VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'PO Import New', ?)
                                """, (part_number, old_price, unit_price, price_change, price_change_percent,
                                      distributor_name, po_number, session.get('username')))
                                # Track this price change for alert
                                price_changes.append({
                                    'part_number': part_number,
                                    'description': description[:50],
                                    'old_price': old_price,
                                    'new_price': unit_price,
                                    'change': price_change,
                                    'change_percent': price_change_percent
                                })
                        
                        # Add to quotation_products table
                        cursor.execute("""
                            INSERT INTO quotation_products (
                                supplier_quotation_id, part_number, description, 
                                unit_price, quantity, currency, system,
                                supplier_name, supplier_type, added_by,
                                po_number, distributor_id
                            ) VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'Distributor', ?, ?, ?)
                        """, (supplier_quotation_id, part_number, description,
                              unit_price, int(quantity), po_system,
                              distributor_name, session.get('username'),
                              po_number, distributor_id))
                else:
                    if quantity_delivered_provided:
                        if quantity_delivered >= quantity:
                            new_delivery_status = 'Delivered'
                        elif quantity_delivered > 0:
                            new_delivery_status = 'Partial'
                        else:
                            new_delivery_status = 'Not Delivered'
                    else:
                        new_delivery_status = 'Not Delivered'
                        quantity_delivered = 0
                    
                    cursor.execute("""
                        INSERT INTO po_items (
                            po_number, item_number, part_number, description, 
                            quantity, unit_price, total_price, 
                            quantity_delivered, delivery_status
                        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """, (po_number, next_item_number, part_number, description, 
                          quantity, unit_price, total_price, quantity_delivered, new_delivery_status))
                    next_item_number += 1
                    items_added += 1
                    
                    # Check if same part_number exists with different price (for price history)
                    if part_number:
                        cursor.execute("""
                            SELECT unit_price FROM quotation_products 
                            WHERE LOWER(TRIM(part_number)) = LOWER(TRIM(?))
                            ORDER BY added_at DESC LIMIT 1
                        """, (part_number,))
                        prev_price_row = cursor.fetchone()
                        if prev_price_row and prev_price_row[0] != unit_price:
                            old_price = prev_price_row[0]
                            price_change = unit_price - old_price
                            price_change_percent = (price_change / old_price * 100) if old_price > 0 else 0
                            cursor.execute("""
                                INSERT INTO product_price_history 
                                (part_number, old_price, new_price, price_change, price_change_percent, 
                                 currency, supplier_name, po_number, source, changed_by)
                                VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'PO Import', ?)
                            """, (part_number, old_price, unit_price, price_change, price_change_percent,
                                  distributor_name, po_number, session.get('username')))
                            # Track this price change for alert
                            price_changes.append({
                                'part_number': part_number,
                                'description': description[:50],
                                'old_price': old_price,
                                'new_price': unit_price,
                                'change': price_change,
                                'change_percent': price_change_percent
                            })
                    
                    # Also add to quotation_products table
                    cursor.execute("""
                        INSERT INTO quotation_products (
                            supplier_quotation_id, part_number, description, 
                            unit_price, quantity, currency, system,
                            supplier_name, supplier_type, added_by,
                            po_number, distributor_id
                        ) VALUES (?, ?, ?, ?, ?, 'SAR', ?, ?, 'Distributor', ?, ?, ?)
                    """, (supplier_quotation_id, part_number, description,
                          unit_price, int(quantity), po_system,
                          distributor_name, session.get('username'),
                          po_number, distributor_id))
                
            except Exception as e:
                errors.append(f"Row {row_idx}: {str(e)}")
        
        conn.commit()
        conn.close()
        
        success_msg = []
        if items_added > 0:
            success_msg.append(f"{items_added} item(s) added")
        if items_updated > 0:
            success_msg.append(f"{items_updated} item(s) updated")
        
        if success_msg:
            flash(f"Excel import successful! {', '.join(success_msg)}", 'success')
        
        if errors:
            flash(f"Some rows had errors: {'; '.join(errors[:5])}", 'warning')
        
        # Store price changes in session for alert display
        if price_changes:
            session['price_changes'] = price_changes
            session['price_changes_po'] = po_number
            flash(f"PRICE_ALERT:{len(price_changes)} price change(s) detected during import!", 'price_alert')
        
    except Exception as e:
        flash(f'Error importing Excel file: {str(e)}', 'danger')
    
    return redirect(url_for('po_profile', po_request_number=po_request_number))


@app.route('/export_po_items_excel/<po_number>')
@login_required
def export_po_items_excel(po_number):
    """Export PO items to Excel file"""
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment
        from io import BytesIO
        
        conn = sqlite3.connect('ProjectStatus.db')
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        
        cursor.execute("""
            SELECT part_number, description, quantity, unit_price, 
                   total_price, quantity_delivered
            FROM po_items
            WHERE po_number = ?
            ORDER BY item_number
        """, (po_number,))
        items = cursor.fetchall()
        conn.close()
        
        workbook = openpyxl.Workbook()
        sheet = workbook.active
        sheet.title = "PO Items"
        
        headers = ['Part Number', 'Description', 'Qty', 'Unit Price', 'Total', 'Delivered']
        
        header_fill = PatternFill(start_color='4472C4', end_color='4472C4', fill_type='solid')
        header_font = Font(bold=True, color='FFFFFF')
        header_alignment = Alignment(horizontal='center', vertical='center')
        
        for col_idx, header in enumerate(headers, start=1):
            cell = sheet.cell(row=1, column=col_idx, value=header)
            cell.fill = header_fill
            cell.font = header_font
            cell.alignment = header_alignment
        
        for row_idx, item in enumerate(items, start=2):
            sheet.cell(row=row_idx, column=1, value=item['part_number'] or '')
            sheet.cell(row=row_idx, column=2, value=item['description'] or '')
            sheet.cell(row=row_idx, column=3, value=item['quantity'] or 0)
            sheet.cell(row=row_idx, column=4, value=item['unit_price'] or 0)
            sheet.cell(row=row_idx, column=5, value=item['total_price'] or 0)
            sheet.cell(row=row_idx, column=6, value=item['quantity_delivered'] or 0)
        
        sheet.column_dimensions['A'].width = 20
        sheet.column_dimensions['B'].width = 50
        sheet.column_dimensions['C'].width = 12
        sheet.column_dimensions['D'].width = 15
        sheet.column_dimensions['E'].width = 15
        sheet.column_dimensions['F'].width = 15
        
        output = BytesIO()
        workbook.save(output)
        output.seek(0)
        
        return send_file(
            output,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=f'PO_{po_number}_Items.xlsx'
        )
        
    except Exception as e:
        flash(f'Error exporting to Excel: {str(e)}', 'danger')
        return redirect(url_for('po_profile', po_number=po_number))


###################################
# Export Complete PO Profile Report to Excel
@app.route('/export_po_profile_excel/<po_request_number>')
@login_required
def export_po_profile_excel(po_request_number):
    """Export comprehensive PO Profile Report to Excel"""
    try:
        import pandas as pd
        from io import BytesIO
        from datetime import datetime
        
        conn = sqlite3.connect('ProjectStatus.db')
        conn.row_factory = sqlite3.Row
        cursor = conn.cursor()
        
        # Get PO details with joins
        cursor.execute("""
            SELECT 
                po.*,
                rp.project_name as project_name_actual,
                d.name as distributor_name,
                v.name as vendor_name,
                e.name as presale_engineer_name,
                pm.name as project_manager_name
            FROM purchase_orders po
            LEFT JOIN register_project rp ON CAST(po.project_name AS INTEGER) = rp.id
            LEFT JOIN distributors d ON CAST(po.distributor AS INTEGER) = d.id
            LEFT JOIN vendors v ON CAST(po.vendor AS INTEGER) = v.id
            LEFT JOIN engineers e ON po.presale_engineer = e.username
            LEFT JOIN engineers pm ON po.project_manager = pm.username
            WHERE po.po_request_number = ?
        """, (po_request_number,))
        po = cursor.fetchone()
        
        if not po:
            flash('Purchase Order not found!', 'danger')
            conn.close()
            return redirect(url_for('view_po_status'))
        
        po_number = po['po_number']
        
        # Get PO items
        cursor.execute("""
            SELECT * FROM po_items 
            WHERE po_number = ? 
            ORDER BY item_number ASC
        """, (po_number,))
        po_items = cursor.fetchall()
        
        # Get delivery notes
        cursor.execute("""
            SELECT * FROM purchase_order_monitoring 
            WHERE (po_number = ? OR po_number = ?) AND deleted_at IS NULL
            ORDER BY order_date DESC
        """, (po_number, po_request_number))
        delivery_notes = cursor.fetchall()
        
        # Get VAT invoices
        cursor.execute("""
            SELECT * FROM vat_invoices 
            WHERE po_request_number = ?
            ORDER BY uploaded_at DESC
        """, (po_request_number,))
        vat_invoices = cursor.fetchall()
        
        conn.close()
        
        # Calculate delivery stats (safely handle missing columns)
        def get_delivery_status(item):
            try:
                return item['delivery_status'] if 'delivery_status' in item.keys() else 'Not Delivered'
            except:
                return 'Not Delivered'
        
        delivered_count = sum(1 for item in po_items if get_delivery_status(item) == 'Delivered')
        partial_count = sum(1 for item in po_items if get_delivery_status(item) == 'Partial')
        not_delivered_count = sum(1 for item in po_items if get_delivery_status(item) == 'Not Delivered')
        total_items = len(po_items)
        
        # Calculate financial summary
        total_value = sum(float(item['total_price'] or 0) for item in po_items)
        vat_amount = total_value * 0.15
        grand_total = total_value + vat_amount
        
        # Create Excel file with multiple sheets
        output = BytesIO()
        with pd.ExcelWriter(output, engine='xlsxwriter') as writer:
            workbook = writer.book
            
            # Formats
            header_format = workbook.add_format({
                'bold': True, 'bg_color': '#667eea', 'font_color': 'white',
                'border': 1, 'align': 'center', 'valign': 'vcenter'
            })
            title_format = workbook.add_format({
                'bold': True, 'font_size': 16, 'font_color': '#667eea'
            })
            label_format = workbook.add_format({
                'bold': True, 'bg_color': '#f0f4ff', 'border': 1
            })
            value_format = workbook.add_format({'border': 1})
            money_format = workbook.add_format({'border': 1, 'num_format': '#,##0.00'})
            
            # Sheet 1: PO Summary
            summary_sheet = workbook.add_worksheet('PO Summary')
            summary_sheet.set_column('A:A', 25)
            summary_sheet.set_column('B:B', 40)
            summary_sheet.set_column('C:C', 25)
            summary_sheet.set_column('D:D', 40)
            
            summary_sheet.write('A1', f'Purchase Order Report - {po_request_number}', title_format)
            summary_sheet.write('A2', f'Generated: {datetime.now().strftime("%Y-%m-%d %H:%M")}')
            
            row = 4
            summary_sheet.write(row, 0, 'PO Details', header_format)
            summary_sheet.merge_range(row, 0, row, 3, 'Purchase Order Details', header_format)
            
            row += 1
            details = [
                ('PO Number', po['po_number'] or 'N/A', 'PO Request Number', po_request_number),
                ('System', po['system'] or 'N/A', 'Status', po['po_approval_status'] or 'N/A'),
                ('Distributor', po['distributor_name'] or 'N/A', 'Vendor', po['vendor_name'] or 'N/A'),
                ('Presale Engineer', po['presale_engineer_name'] or 'N/A', 'Project Manager', po['project_manager_name'] or 'N/A'),
                ('Project', po['project_name_actual'] or 'N/A', 'Created Date', str(po['created_at'])[:10] if po['created_at'] else 'N/A'),
                ('Delivery Status', po['po_delivery_status'] or 'N/A', 'Vendor Notes', (po['po_notes_vendor'] or 'N/A')[:50])
            ]
            
            for label1, val1, label2, val2 in details:
                summary_sheet.write(row, 0, label1, label_format)
                summary_sheet.write(row, 1, val1, value_format)
                summary_sheet.write(row, 2, label2, label_format)
                summary_sheet.write(row, 3, val2, value_format)
                row += 1
            
            row += 2
            summary_sheet.merge_range(row, 0, row, 1, 'Delivery Summary', header_format)
            summary_sheet.merge_range(row, 2, row, 3, 'Financial Summary', header_format)
            
            row += 1
            summary_sheet.write(row, 0, 'Total Items', label_format)
            summary_sheet.write(row, 1, total_items, value_format)
            summary_sheet.write(row, 2, 'Subtotal', label_format)
            summary_sheet.write(row, 3, total_value, money_format)
            
            row += 1
            summary_sheet.write(row, 0, 'Delivered', label_format)
            summary_sheet.write(row, 1, delivered_count, value_format)
            summary_sheet.write(row, 2, 'VAT (15%)', label_format)
            summary_sheet.write(row, 3, vat_amount, money_format)
            
            row += 1
            summary_sheet.write(row, 0, 'Partial', label_format)
            summary_sheet.write(row, 1, partial_count, value_format)
            summary_sheet.write(row, 2, 'Grand Total', label_format)
            summary_sheet.write(row, 3, grand_total, money_format)
            
            row += 1
            summary_sheet.write(row, 0, 'Not Delivered', label_format)
            summary_sheet.write(row, 1, not_delivered_count, value_format)
            
            # Sheet 2: PO Items
            if po_items:
                items_data = []
                for item in po_items:
                    # Safely access columns that might not exist
                    try:
                        qty_delivered = item['quantity_delivered'] if 'quantity_delivered' in item.keys() else 0
                    except:
                        qty_delivered = 0
                    try:
                        del_status = item['delivery_status'] if 'delivery_status' in item.keys() else 'Not Delivered'
                    except:
                        del_status = 'Not Delivered'
                    
                    items_data.append({
                        'Item #': item['item_number'] or '',
                        'Part Number': item['part_number'] or '',
                        'Description': item['description'] or '',
                        'Quantity': item['quantity'] or 0,
                        'Unit Price': float(item['unit_price'] or 0),
                        'Total Price': float(item['total_price'] or 0),
                        'Qty Delivered': qty_delivered or 0,
                        'Delivery Status': del_status or 'Not Delivered'
                    })
                items_df = pd.DataFrame(items_data)
                items_df.to_excel(writer, sheet_name='PO Items', index=False, startrow=1)
                
                items_sheet = writer.sheets['PO Items']
                items_sheet.write('A1', 'PO Items List', title_format)
                for col, header in enumerate(items_df.columns):
                    items_sheet.write(1, col, header, header_format)
                    items_sheet.set_column(col, col, 18 if col == 2 else 14)
            
            # Sheet 3: Delivery Notes
            if delivery_notes:
                dn_data = []
                for dn in delivery_notes:
                    dn_data.append({
                        'ID': dn['id'] or '',
                        'Order Date': str(dn['order_date'])[:10] if dn['order_date'] else '',
                        'Expected Delivery': str(dn['expected_delivery'])[:10] if dn['expected_delivery'] else '',
                        'Status': dn['status'] or '',
                        'Notes': dn['notes'] or ''
                    })
                dn_df = pd.DataFrame(dn_data)
                dn_df.to_excel(writer, sheet_name='Delivery Notes', index=False, startrow=1)
                
                dn_sheet = writer.sheets['Delivery Notes']
                dn_sheet.write('A1', 'Delivery Notes', title_format)
                for col, header in enumerate(dn_df.columns):
                    dn_sheet.write(1, col, header, header_format)
                    dn_sheet.set_column(col, col, 20)
            
            # Sheet 4: VAT Invoices
            if vat_invoices:
                vat_data = []
                for inv in vat_invoices:
                    vat_data.append({
                        'Invoice Name': inv['invoice_name'] or '',
                        'File Name': inv['file_name'] or '',
                        'Uploaded By': inv['uploaded_by_username'] or '',
                        'Upload Date': str(inv['uploaded_at'])[:10] if inv['uploaded_at'] else ''
                    })
                vat_df = pd.DataFrame(vat_data)
                vat_df.to_excel(writer, sheet_name='VAT Invoices', index=False, startrow=1)
                
                vat_sheet = writer.sheets['VAT Invoices']
                vat_sheet.write('A1', 'VAT Invoices', title_format)
                for col, header in enumerate(vat_df.columns):
                    vat_sheet.write(1, col, header, header_format)
                    vat_sheet.set_column(col, col, 18)
        
        output.seek(0)
        
        filename = f'PO_Report_{po_request_number}_{datetime.now().strftime("%Y%m%d")}.xlsx'
        
        return send_file(
            output,
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=filename
        )
        
    except Exception as e:
        flash(f'Error exporting PO Report: {str(e)}', 'danger')
        return redirect(url_for('po_profile', po_request_number=po_request_number))


