def view_vat_invoice(invoice_id):
    """View a specific VAT invoice PDF"""
    conn = sqlite3.connect('ProjectStatus.db')
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()
    
    cursor.execute("SELECT * FROM vat_invoices WHERE id = ?", (invoice_id,))
